insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('wiina-klassizismus', 'Wiina Klassizismus', '', '', '', '', 'Wiener Klassizismus', '[{"kategorie": "allg.", "text": "\"architektonischer und künstlerischer Stil, der sich in Wien vor allem im späten 18. und frühen 19. Jahrhundert etablierte\""}, {"kategorie": "", "text": "Er orientierte sich an den ästhetischen Idealen der griechischen und römischen Antike und steht im Kontrast zum vorangegangenen opulenten Barock und Rokoko"}, {"kategorie": "", "text": "Der Klassizismus betonte klare, harmonische Formen, schlichte Eleganz und eine Rückkehr zur klassischen Ordnung und Symmetrie"}, {"kategorie": "", "text": "Klassizistische Gebäude in Wien sind häufig monumental angelegt und vermitteln eine Aura von Erhabenheit und Macht. Dabei wird die antike Tempelarchitektur oft als Inspirationsquelle genutzt"}, {"kategorie": "", "text": "Typische Merkmale sind Säulen, Pilaster, Kapitelle, Architrave und Gesimse, die die antiken Vorbilder nachahmen. Auch Portale mit Tempelgiebeln und Hauptfassaden im Stil von antiken Tempeln sind häufig zu finden"}, {"kategorie": "", "text": "Beispiele für klassizistische Architektur in Wien sind der Theseustempel im Wiener [[Volksgarten]] und das Österreichische [[Parlament]], eines der monumentalsten klassizistischen Gebäude Wiens."}]'::jsonb, ''),
  ('easchde-tiaknbelogarung', 'Easchde Tiaknbelogarung', '', '', '', '', 'Erste Türkenbelagerung', '[{"kategorie": "allg.", "text": "\" erster großer Versuch des Osmanischen Reiches, die österreichische Hauptstadt Wien im Jahr 1529 zu erobern\""}, {"kategorie": "", "text": "Sie war Teil des jahrhundertelangen Konflikts zwischen dem Osmanischen Reich und dem [[Habsburgerreich]] um die Vorherrschaft in Mitteleuropa"}, {"kategorie": "", "text": "Die Osmanen unter Sultan Süleyman dem Prächtigen hatten 1526 in der Schlacht von Mohács die ungarische Armee besiegt und das Königreich Ungarn zerschlagen. König Ludwig II. von Ungarn starb in der Schlacht, und große Teile Ungarns fielen unter osmanische Kontrolle"}, {"kategorie": "", "text": "Nach dem Sieg über Ungarn sahen die Osmanen Wien als das nächste strategische Ziel, um ihre Herrschaft in Mitteleuropa auszudehnen und die habsburgische Macht zu schwächen. Wien, die Hauptstadt des Habsburgerreiches, war ein Symbol für die christliche Verteidigung gegen die osmanische Expansion"}, {"kategorie": "", "text": "Sultan Süleyman führte eine große Armee von etwa 100.000 bis 120.000 Soldaten nach Wien. Die Stadt selbst war schlecht auf die Belagerung vorbereitet, da die Stadtmauern veraltet und die Verteidigungsanlagen nicht ausreichend waren"}, {"kategorie": "", "text": "Wien wurde von etwa 20.000 Verteidigern unter der Führung von Niklas Graf Salm verteidigt, darunter Soldaten und Bürger der Stadt. Trotz der zahlenmäßigen Überlegenheit der Osmanen entschloss sich die Stadt zur Verteidigung"}, {"kategorie": "", "text": "Die osmanischen Truppen belagerten Wien ab 27. September 1529, setzten schweres Belagerungsgerät ein und versuchten, die Stadtmauern zu untergraben und zu stürmen"}, {"kategorie": "", "text": "rotz der osmanischen Angriffe gelang es den Verteidigern, die Stadt zu halten. Die Osmanen stießen auf erbitterten Widerstand, und die Wiener nutzten geschickt das schwierige Wetter und die schlechten Versorgungsbedingungen der Osmanen aus"}, {"kategorie": "", "text": "Sultan Süleyman sah sich gezwungen, die Belagerung am 14. Oktober 1529 abzubrechen und sich mit seiner Armee zurückzuziehen. Wien blieb unbesiegt, und die Habsburger konnten ihre Hauptstadt erfolgreich verteidigen"}]'::jsonb, ''),
  ('zweite-tiaknbelogarung', 'Zweite Tiaknbelogarung', '', '', '', '', 'Zweite Türkenbelagerung', '[{"kategorie": "allg.", "text": "\"letzter großer Versuch des Osmanischen Reiches, Wien und damit das Herz des [[Habsburgerreichs]] im Jahr 1683 zu erobern\""}, {"kategorie": "", "text": "Unter Sultan Mehmed IV. entschloss sich das Osmanische Reich zu einem neuen Angriff auf Wien, um die habsburgische Macht zu schwächen und weiter nach Mitteleuropa vorzudringen. Großwesir Kara Mustafa führte die osmanische Armee in diese Kampagne"}, {"kategorie": "", "text": "Die osmanische Armee, die etwa 150.000 Mann stark war, erreichte im Juli 1683 die Umgebung von Wien. Die Verteidiger der Stadt, unter der Führung von Ernst Rüdiger von Starhemberg, verfügten nur über etwa 15.000 bis 20.000 Soldaten, waren aber gut organisiert"}, {"kategorie": "", "text": "Am 14. Juli 1683 begann die Belagerung Wiens. Die Osmanen belagerten die Stadt von allen Seiten und versuchten, mit Graben- und Tunnelarbeiten die Stadtmauern zu unterminieren und zu sprengen. Die Wiener Bevölkerung und die Verteidiger waren jedoch entschlossen, die Stadt zu halten, obwohl sie unter starkem Druck standen"}, {"kategorie": "", "text": "Die Habsburger hatten bereits Hilfe von ihren Verbündeten erbeten, darunter dem Polnisch-Litauischen Königreich und dem Heiligen Römischen Reich. Die entscheidende Rettung kam in Form eines großen Entsatzheeres unter der Führung von König Jan III. Sobieski von Polen. Dieses vereinte christliche Heer bestand aus etwa 70.000 bis 80.000 Soldaten"}, {"kategorie": "", "text": "Am 12. September 1683 kam es zur entscheidenden Schlacht am [[Kahlenberg]], einem Hügel nordwestlich von Wien. Das christliche Entsatzheer griff die osmanischen Belagerer an, und in einem spektakulären Sieg konnten sie die Osmanen besiegen und Wien von der Belagerung befreien. Besonders bekannt wurde dabei der polnische Kavallerieangriff (Husaren), der den Osmanen den endgültigen Schlag versetzte."}]'::jsonb, ''),
  ('haus-hof-und-staatsarchiv', 'Haus-, Hof- und Staatsarchiv', '', '', '', '', 'Haus-, Hof- und Staatsarchiv', '[{"kategorie": "allg.", "text": "\"eines der bedeutendsten historischen Archive Österreichs\""}, {"kategorie": "", "text": "Es befindet sich am Minoritenplatz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und bewahrt zentrale Dokumente der [[Habsburgermonarchie]] sowie der österreichischen Außenpolitik"}, {"kategorie": "", "text": "Das Archiv ist eine der wichtigsten Quellen für die Geschichte Österreichs, Mitteleuropas und darüber hinaus, da es über mehrere Jahrhunderte hinweg die Staatsgeschäfte und die Herrschaft der Habsburger dokumentiert"}, {"kategorie": "", "text": "Das Haus-, Hof- und Staatsarchiv geht auf das 16. Jahrhundert zurück. Es entstand, um die wichtigen Dokumente der königlichen und kaiserlichen Verwaltung zu bewahren und zu organisieren"}, {"kategorie": "", "text": "Der Name \"Haus-, Hof- und Staatsarchiv\" beschreibt die verschiedenen Funktionsebenen: (i) Hausarchiv (Verwahrung der Urkunden und Dokumente, die die dynastischen Angelegenheiten des Hauses Habsburg betreffen, darunter Familienurkunden, Heiratsverträge und Testamente);  (ii) Hofarchiv (Aufzeichnungen und Dokumente, die sich auf die Verwaltung des Hofes beziehen, darunter Hofordnungen, Personalakten und Finanzen); sowie (iii) Staatsarchiv: Hier werden die außen- und innenpolitischen Dokumente der Habsburgermonarchie aufbewahrt, die die Staatsführung und diplomatischen Beziehungen betreffen"}, {"kategorie": "", "text": "Im 19. Jahrhundert erlebte das Archiv eine Modernisierung und wurde 1848 neu organisiert. Mit dem Ende der Habsburgermonarchie 1918 blieb das Archiv bestehen und dokumentiert seither auch die Geschichte der Ersten Republik, der Zweiten Republik sowie der österreichischen Außenpolitik nach 1945"}, {"kategorie": "", "text": "Das Archiv ist öffentlich zugänglich, und viele seiner Bestände wurden digitalisiert, um Forschern weltweit den Zugang zu ermöglichen."}]'::jsonb, ''),
  ('oestarreichisches-schdoodsarchiv', 'Östarreichisches Schdoodsarchiv', '', '', '', '', 'Österreichisches Staatsarchiv', '[{"kategorie": "allg.", "text": "\"zentrales Archiv der Republik Österreich, welches das Archivgut des Bundes sowie bedeutende historische Dokumente und Sammlungen verwahrt\""}, {"kategorie": "", "text": "Es wurde 1945 gegründet, indem mehrere ältere Teilarchive unter einer Generaldirektion zusammengeführt wurden. Zu den wichtigsten Abteilungen gehören das [[Haus-]], Hof- und Staatsarchiv, das Allgemeine Verwaltungsarchiv, das Finanz- und Hofkammerarchiv, das Kriegsarchiv und das Archiv der Republik"}, {"kategorie": "", "text": "Die Vorgeschichte des staatlichen Archivwesens in Österreich reicht bis ins Jahr 1502 zurück, als Kaiser [[Maximilian]] I. die geordnete Sammlung von Dokumenten in Wien befahl. Das eigentliche [[Haus-]], Hof- und Staatsarchiv wurde jedoch erst 1749 unter Kaiserin [[Maria]] Theresia gegründet, um die Dokumente der [[Habsburgermonarchie]] zu zentralisieren. Nach dem Zweiten Weltkrieg wurden diese verschiedenen historischen Archive zu einem zentralen Staatsarchiv zusammengefasst"}, {"kategorie": "", "text": "Das Österreichische Staatsarchiv verwahrt eine Vielzahl von Dokumenten, die von der mittelalterlichen Verwaltung bis zur modernen Republik reichen. Dazu gehören das Schriftgut des [[römisch-deutschen]] Reiches, des [[Kaisertums]] Österreich (1804–1918) und der [[Republik]] Österreich (seit 1918). Die Bestände umfassen Urkunden, Akten, Nachlässe, Karten- und Plansammlungen sowie eine bedeutende Präsenzbibliothek"}, {"kategorie": "", "text": "Während einige Abteilungen wie das [[Haus-]], Hof- und Staatsarchiv in historischen Gebäuden wie am [[Minoritenplatz]] in Wien untergebracht sind, befinden sich die meisten Abteilungen im modernen Zentralarchivgebäude in der [[Nottendorfer]] Gasse im Stadtteil [[Erdberg]] (3. Bezirk, [[Landstraße]]), das zwischen 1981 und 1986 erbaut wurde. Das Zentralarchiv umfasst auch Restaurierungswerkstätten und eine Reproabteilung."}]'::jsonb, ''),
  ('nottnduafa-gossn', 'Nottnduafa Gossn', '', '', '', '', 'Nottendorfer Gasse', '[{"kategorie": "allg.", "text": "\"Straße im 3. Wiener Gemeindebezirk ([[Landstraße]]), welche nach der ausgelöschten Ortschaft \"Nottendorf\" benannt wurde\""}, {"kategorie": "", "text": "Nottendorf war eine Ansiedlung im Bereich des heutigen Stadtteils [[Erdberg]] und wurde erstmals im Jahr 1389 urkundlich erwähnt. Der Name „Nottendorf“ bedeutet im Niederdeutschen „Dorf der Genossen“"}, {"kategorie": "", "text": "Die Siedlung wurde gegen Ende des 14. Jahrhunderts von flämischen Gärtnern und Wollfärbern gegründet, die unter der Herrschaft von Albrecht III. ins Land berufen wurden, um das Gebiet des Auwalds urbar zu machen. Die Siedlung hatte eine genossenschaftliche Dorfverfassung und erstreckte sich vom Gebiet der heutigen [[Erdberger]] Pfarrkirche über den [[Kardinal-Nagl-Platz]] bis zur [[Leonhardgasse]]"}, {"kategorie": "", "text": "Während der [[Ersten]] Türkenbelagerung im Jahr 1529 wurde Nottendorf vollständig zerstört und nie wieder aufgebaut. Die Nottendorfer Gasse erinnert heute an diese historische Siedlung"}, {"kategorie": "", "text": "Heute befindet sich an der Nottendorfer Gasse u.a. auch das [[Bundesamtsgebäude]] Erdberg mit dem [[Österreichischen]] Staatsarchiv."}]'::jsonb, ''),
  ('pfoakiachn-eadbeag', 'Pfoakiachn Eadbeag', '', '', '', '', 'Pfarrkirche Erdberg', '[{"kategorie": "", "text": "Sie wird im Volksmund zur besseren Unterscheidung von der [[Pfarrkirche]] Neuerdberg auch als \"Pfarrkirche Alt-Erdberg\" bezeichnet. Der Bau, der den Heiligen Petrus und Paulus geweiht ist, wurde zwischen 1700 und 1723 im barock-klassizistischen Stil errichtet und steht heute unter Denkmalschutz"}, {"kategorie": "", "text": "Die Kirche befindet sich an einer erhöhten Stelle über der [[Erdbergstraße]], wo sich früher das Ortszentrum der alten Ortschaft [[Erdberg]] befand. An dieser Stelle soll bereits im Jahr 1234 eine Kapelle gestanden haben, welche erstmals 1333 urkundlich erwähnt wurde"}, {"kategorie": "", "text": "Die heutige Kirche wurde auf den Ruinen einer Kapelle errichtet, die während der [[Zweiten]] Türkenbelagerung (1683) zerstört wurde. Ursprünglich war der Bau nur als Totenkapelle für den umliegenden Friedhof gedacht, wurde aber später zu einer vollständigen Pfarrkirche erweitert"}, {"kategorie": "", "text": "Die Kirche wurde mehrmals renoviert, zuletzt in den Jahren 1985 und 1986. Das Innere ist reich an barocker Ausstattung, darunter ein Hochaltar mit einem Bild, das den Abschied der Apostel Petrus und Paulus darstellt"}, {"kategorie": "", "text": "Die Orgel der Kirche stammt aus dem Jahr 1885 und wurde 1993 in die Pfarrkirche Erdberg versetzt."}]'::jsonb, ''),
  ('kardinal-nogl-plotz', 'Kardinal-Nogl-Plotz', '', '', '', '', 'Kardinal-Nagel-Platz', '[{"kategorie": "allg.", "text": "\"zentraler und belebter Platz im 3. Wiener Gemeindebezirk ([[Landstraße]]), im Stadtteil [[Erdberg]]\""}, {"kategorie": "", "text": "Er verbindet mehrere wichtige Straßen wie die [[Erdbergstraße]] und die [[Apostelgasse]] und dient als Verkehrsknotenpunkt"}, {"kategorie": "", "text": "Der Platz ist nach Franz Xaver Nagl (1855–1913) benannt, einem bedeutenden Kirchenmann und Kardinal der Erzdiözese Wien. Franz Xaver Nagl war ein österreichischer Priester und Theologe, der 1911 zum Fürsterzbischof von Wien ernannt und im selben Jahr zum Kardinal erhoben wurde"}, {"kategorie": "", "text": "Seine Laufbahn umfasste unter anderem das Amt des Bischofs von Triest-Capo d''Istria und verschiedene bedeutende Positionen in der römisch-katholischen Kirche. Nagl widmete sich der Modernisierung der Seelsorge und dem Kirchenbau in Wien. Er organisierte 1912 den 23. Internationalen Eucharistischen Weltkongress in Wien, ein Höhepunkt seiner Amtszeit"}, {"kategorie": "", "text": "Der Kardinal-Nagl-Platz wird auch durch den gleichnamigen Kardinal-Nagl-Park und die Station der U-Bahnlinie U3 geprägt. Er ist ein zentraler Treffpunkt für die Bewohner des Bezirks und trägt zur lebendigen, aber zugleich entspannten Atmosphäre des Viertels bei"}, {"kategorie": "", "text": "Durch die Kombination aus Verkehrsknotenpunkt, Geschäften und der Parkanlage ist der Kardinal-Nagl-Platz sowohl ein belebtes als auch ein grünes Zentrum im 3. Bezirk."}]'::jsonb, ''),
  ('thomas-klestil-plotz', 'Thomas-Klestil-Plotz', '', '', '', '', 'Thomas-Klestil-Platz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 3. Wiener Gemeindebezirk ([[Landstraße]]), im Stadtteil [[Erdberg]], der nach dem ehemaligen Bundespräsidenten Thomas Klestil benannt ist\""}, {"kategorie": "", "text": "Klestil war ein echter \"Erdberger\", geboren und aufgewachsen in einer Straßenbahnerfamilie in diesem Viertel. Später besuchte er auch das Gymnasium in der [[Hagenmüllergasse]], das sich ebenfalls in [[Erdberg]] befindet"}, {"kategorie": "", "text": "Durch die Gestaltung des Platzes als weitläufiger, offener Raum wird der Platz sowohl als Ort für Fußgänger als auch für Anwohner und Besucher genutzt, die in den umliegenden Büro- und Wohngebäuden arbeiten oder leben"}, {"kategorie": "", "text": "Er ist eingebettet in eine stark urbanisierte Umgebung ([[TownTown]]), die durch innovative Bauprojekte der letzten Jahrzehnte geprägt wurde und gleichzeitig eine Verbindung zur historischen Entwicklung des Bezirks hat"}, {"kategorie": "", "text": "Der Platz ehrt nicht nur Klestils politische Karriere und Verdienste als Diplomat und Bundespräsident, sondern verweist auch auf seine tiefen lokalen Wurzeln im Bezirk, den er nie aus den Augen verlor. Mit seiner urbanen und modernen Gestaltung verbindet der Thomas-Klestil-Platz somit die Geschichte eines der bedeutendsten Söhne des Bezirks mit der zeitgenössischen Stadtentwicklung Wiens."}]'::jsonb, ''),
  ('taun-taun', 'Taun-Taun', '', '', '', '', 'Town-Town', '[{"kategorie": "allg.", "text": "\"modernes Wirtschafts- und Geschäftsviertel im Stadtteil [[Erdberg]] des 3. Wiener Gemeindebezirks ([[Landstraße]]), das sich entlang der Entwicklungsachse zwischen der Innenstadt und dem Flughafen Wien-Schwechat erstreckt\""}, {"kategorie": "", "text": "Dieser eigenständige Stadtteil wurde auf einem 19 Hektar großen Gebiet errichtet, das zuvor von Schrebergärten, alten Gemüsefeldern und aufgegebenen Fabriken geprägt war. Die Entwicklung von Town-Town begann im Jahr 2000 und umfasst zahlreiche hochmoderne Bürotürme, die multinationale Konzerne anziehen sollen, insbesondere mit Blick auf die Ostorientierung Wiens und die EU-Osterweiterung"}, {"kategorie": "", "text": "Das Gebiet ist hervorragend an das öffentliche Verkehrsnetz angebunden, insbesondere durch die U-Bahn-Linie U3, sowie an die Autobahnen A4 ([[Ostautobahn]]) und [[A]]23"}, {"kategorie": "", "text": "Der Ausbauplan sieht auch ein Shopping-Plaza als zentrales Element vor, um das sich zahlreiche Bürokomplexe gruppieren. Architektonisch wurde das Projekt von renommierten Architekturbüros wie Coop Himmelb(l)au und Peichl & Partner gestaltet, um eine architektonische Vielfalt zu gewährleisten"}, {"kategorie": "", "text": "Die Ansiedlung internationaler Unternehmen, wie etwa der Deutschen Telekom, spiegelt die strategische Bedeutung von Town-Town als Zentrum für wirtschaftliche Aktivitäten im Osten Wiens wider."}]'::jsonb, ''),
  ('kaisatum-oestarreich', 'Kaisatum Östarreich', '', '', '', '', 'Kaisertum Österreich', '[{"kategorie": "allg.", "text": "\"offizieller Staatsname der [[Donaumonarchie]] von 1804 bis 1867\""}, {"kategorie": "", "text": "Das Kaisertum Österreich war ein Vielvölkerstaat in Mitteleuropa, der am 11. August 1804 von [[Erzherzog]] Franz von Österreich gegründet wurde, nachdem er sich zum Kaiser von Österreich ausrief, um der zunehmenden Macht von Napoleon Bonaparte und dessen Kaiserkrönung in Frankreich zu begegnen. Franz II., der bis dahin als Kaiser des [[Heiligen]] Römischen Reiches amtierte, führte nach der Auflösung des Reiches 1806 den Titel als [[Franz]] I. von Österreich weiter"}, {"kategorie": "", "text": "Nach dem Vorbild von Napoleons Kaiserkrönung wollte Franz von Österreich das Prestige der Habsburger-Dynastie sichern und schuf das Kaisertum Österreich als neues, zentrales Staatsgebilde"}, {"kategorie": "", "text": "In den folgenden Jahren war das Kaisertum in die Koalitionskriege gegen Napoleon verwickelt, die zu schweren territorialen Verlusten führten, darunter Tirol, Venetien und andere Gebiete. Der [[Wiener]] Kongress (1814–1815) stellte den territorialen Status weitgehend wieder her"}, {"kategorie": "", "text": "Im Jahr 1867 wurde das Kaisertum Österreich durch den [[Österreichisch-Ungarischen]] Ausgleich in die [[Doppelmonarchie]] Österreich-Ungarn umgewandelt. Ungarn erhielt eine weitgehende Autonomie innerhalb der Monarchie, was zur Schaffung von zwei gleichwertigen Staaten führte: [[Cisleithanien]] (Österreich) und [[Transleithanien]] (Ungarn). Dieser Schritt beendete formal das Kaisertum Österreich, doch der österreichische Kaiser blieb gleichzeitig König von Ungarn"}, {"kategorie": "", "text": "Das Kaisertum Österreich war ein Vielvölkerstaat mit über 21 Millionen Einwohnern, die verschiedenen Nationalitäten und Kulturen angehörten, darunter Deutsche, Ungarn, Tschechen, Slowaken, Polen, Ruthenen, Rumänen, Italiener, Kroaten, Serben und Slowenen. Diese Vielfalt prägte das Reich kulturell, politisch und sozial. Die ethnische und sprachliche Vielfalt war auch eine Herausforderung für die zentralistische Herrschaft und die Verwaltung des Reiches"}, {"kategorie": "", "text": "Mit der Umwandlung in [[Österreich-Ungarn]] 1867 endete die Geschichte des Kaisertums Österreich, aber es hinterließ tiefgreifende kulturelle und politische Spuren in den Nachfolgestaaten."}]'::jsonb, ''),
  ('pfoakiachn-nei-eadbeag', 'Pfoakiachn Nei-Eadbeag', '', '', '', '', 'Pfarrkirche Neu-Erdberg', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 3. Wiener Gemeindebezirk ([[Landstraße]], im Bezirksteil [[Erdberg]] an der [[Hagenmüllergasse]] 33 (auch als \"Pfarrkirche Don Bosco\" bekannt)"}, {"kategorie": "", "text": "Die Kirche wurde zwischen 1954 und 1958 errichtet und dem heiligen Johannes Bosco geweiht. Das Gebäude steht heute unter Denkmalschutz"}, {"kategorie": "", "text": "Die Geschichte der Pfarre reicht zurück bis in die Jahre 1908 bis 1910, als die Salesianer Don Boscos das Salesianum mit einer Kapelle errichteten, die den heiligen Schutzengeln geweiht war. Diese Kapelle wurde 1939 zur Pfarrkirche erhoben und nach den Zerstörungen des [[Zweiten]] Weltkriegs neu gestaltet"}, {"kategorie": "", "text": "Architektonisch ist die Pfarrkirche Neuerdberg ein längsgerichteter Stahlbetonbau mit Beton-Maßwerkfenstern und einem markanten Kirchturm. Der Turm diente früher als Wohnturm für Schülergruppen, ist aber derzeit aufgrund von Baufälligkeit gesperrt"}, {"kategorie": "", "text": "Das Innere der Kirche wird von nur vier Pfeilern gestützt, was eine gute Sicht auf den Altarraum von fast allen Plätzen ermöglicht. Die Decke des Mittelschiffs ist als Zeltkonstruktion gestaltet, was dem Raum eine besondere Atmosphäre verleiht. Die künstlerisch gestalteten Glasfenster stammen von namhaften Künstlern und zeigen Symbole des Kirchenjahres und christliche Themen"}, {"kategorie": "", "text": "Die Orgel der Kirche, ein Werk von Gregor Hradetzky aus dem Jahr 1964, hat 20 Register, zwei Manuale und ein Pedal. Sie wurde 1965 geweiht und spielt bis heute eine zentrale Rolle im musikalischen Leben der Pfarre."}]'::jsonb, ''),
  ('neiche-buag', 'Neiche Buag', '', '', '', '', 'Neue Burg', '[{"kategorie": "allg.", "text": "\"monumentaler Teil des [[Hofburg-Komplexes]] zwischen [[Heldenplatz]] und [[Burggarten]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Die Neue Burg wurde im späten 19. und frühen 20. Jahrhundert als Erweiterung der Hofburg errichtet und ist heute ein wichtiges kulturelles Zentrum. Sie beherbergt mehrere Museen und Institutionen und ist architektonisch ein herausragendes Beispiel des [[Historismus]]"}, {"kategorie": "", "text": "Die Neue Burg wurde als Teil eines umfassenden Erweiterungsprojekts der Hofburg geplant, das gegen Ende des 19. Jahrhunderts begann. Die Idee hinter dem Projekt war, die Hofburg, die Residenz der Habsburger, zu vergrößern und repräsentative Räume für den Kaiser und das Kaiserreich zu schaffen"}, {"kategorie": "", "text": "Die Neue Burg ist ein prächtiges Beispiel für den [[Historismus]], einem architektonischen Stil, der historische Baustile aufgriff und kombinierte. Die Fassaden zeigen Anleihen aus der Renaissance und dem Barock"}, {"kategorie": "", "text": "Auffällig ist der große, halbkreisförmige Bau, der mit seinen imposanten Säulen, Skulpturen und Reliefs eindrucksvoll die Macht und den Glanz der Habsburgerdynastie repräsentieren sollte"}, {"kategorie": "", "text": "In der Mitte des Hofes, vor der Neuen Burg am [[Heldenplatz]], steht das Reiterdenkmal von [[Prinz]] Eugen von Savoyen, einem der bedeutendsten Feldherren der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Die Neue Burg erlangte auch traurige Berühmtheit, da Adolf Hitler 1938 von einem der Balkone der Neuen Burg aus den Anschluss Österreichs an das [[Deutsche]] Reich proklamierte. Dieses historische Ereignis ist ein bedeutsamer Teil der Geschichte der Neuen Burg und Wiens"}, {"kategorie": "", "text": "Heute beherbergt die Neue Burg mehrere bedeutende Museen und Institutionen, darunter (i) das [[Weltmuseum]] Wien (eines der weltweit bedeutendsten ethnologischen Museen, das Sammlungen aus Afrika, Asien, Ozeanien und Amerika zeigt);  (ii) die [[Hofjagd-]] und Rüstkammer (eine der größten und umfassendsten Sammlungen an historischen Waffen und Rüstungen in Europa);  (iii) das [[Ephesos]] Museum (hier werden archäologische Funde aus der antiken Stadt Ephesos (im heutigen Türkei) gezeigt, die bei österreichischen Ausgrabungen entdeckt wurden);  sowie Teile der [[Österreichischen]] Nationalbibliothek (darunter Sammlungen historischer Manuskripte und Dokumente)"}]'::jsonb, ''),
  ('hofjogd-und-ruestkaumma', 'Hofjogd- und Rüstkaumma', '', '', '', '', 'Hofjagd- und Rüstkammer', '[{"kategorie": "allg.", "text": "\"eine der bedeutendsten historischen Sammlungen von Waffen, Rüstungen, Kunstobjekten und Jagdutensilien in Europa\""}, {"kategorie": "", "text": "Sie befindet sich in der [[Neuen]] Burg, die Teil des [[Hofburg-Komplexes]] in Wien ist"}, {"kategorie": "", "text": "Die Sammlung gibt einen tiefen Einblick in die militärische Geschichte und das höfische Leben der Habsburgerdynastie und umfasst zahlreiche wertvolle und kunstvoll gearbeitete Objekte aus mehreren Jahrhunderten"}, {"kategorie": "", "text": "Die Sammlung geht auf die Habsburger zurück, die als Kaiser des Heiligen Römischen Reiches und später als Kaiser von Österreich eine zentrale Rolle in der europäischen Politik spielten. Sie sammelten nicht nur Waffen und Rüstungen für den militärischen Gebrauch, sondern auch für zeremonielle und repräsentative Zwecke"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte wurden zahlreiche Rüstungen und Waffen, die für Feldzüge, Turniere und Repräsentationszwecke verwendet wurden, zusammengetragen. Auch die Jagd spielte eine wichtige Rolle am kaiserlichen Hof, was sich in der Sammlung von Jagdwaffen und -ausrüstung widerspiegelt"}, {"kategorie": "", "text": "Eine besonders wertvolle und kunstvolle Rüstung ist die Ritterrüstung von Kaiser [[Maximilian]] I., die im späten 15. Jahrhundert gefertigt wurde und als Meisterwerk der Rüstungsschmiedekunst gilt"}, {"kategorie": "", "text": "Auch die sogenannten \"Türkenbeuten\" (Waffen und Rüstungen, die während der Türkenkriege erbeutet wurden) gehören zu den bedeutenden Exponaten der Sammlung"}, {"kategorie": "", "text": "Die Hofjagd- und Rüstkammer ist nicht nur ein militärhistorisches Museum, sondern zeigt auch die Kunstfertigkeit der Waffenschmiede, Rüstungsmacher und Juweliere der damaligen Zeit. Viele der ausgestellten Stücke wurden nicht nur für den Gebrauch gefertigt, sondern auch als Statussymbole, die den Reichtum und die Macht der Habsburger und anderer europäischer Fürsten demonstrierten."}]'::jsonb, ''),
  ('ephesos-museum', 'Ephesos-Museum', '', '', '', '', 'Ephesos-Museum', '[{"kategorie": "allg.", "text": "\"bedeutendes archäologisches Museum in Wien, das sich in der [[Neuen]] Burg (Teil des [[Hofburg-Komplexes]]) befindet\""}, {"kategorie": "", "text": "Es zeigt Funde aus den österreichischen Ausgrabungen in der antiken Stadt Ephesos, die heute in der Türkei liegt"}, {"kategorie": "", "text": "Ephesos war eine der wichtigsten Städte der Antike und ist insbesondere für den Tempel der Artemis, eines der Sieben Weltwunder, berühmt"}, {"kategorie": "", "text": "Das Ephesos-Museum ist Teil des [[Kunsthistorischen]] Museums Wien und bietet faszinierende Einblicke in das Leben und die Kunst der antiken griechisch-römischen Welt"}, {"kategorie": "", "text": "Die Geschichte des Ephesos-Museums ist eng mit den österreichischen Ausgrabungen in Ephesos verbunden, die ab 1895 unter der Leitung von Otto Benndorf, einem österreichischen Archäologen, begannen. Diese Ausgrabungen wurden im Rahmen einer Vereinbarung mit der osmanischen Regierung durchgeführt, die den österreichischen Archäologen Zugang zu der antiken Stadt gewährte"}, {"kategorie": "", "text": "Im Zuge dieser Ausgrabungen wurden zahlreiche Funde gemacht, darunter Skulpturen, Architekturfragmente und Alltagsgegenstände, die heute im Ephesos-Museum ausgestellt sind, darunter (i) das Partherdenkmal (ein riesiges Relief, das zu Ehren eines römischen Sieges über die Parther errichtet wurde. Es zeigt Szenen aus der römischen Militärgeschichte und ist ein herausragendes Beispiel für römische Monumentalkunst;  (ii) die berühmte Statue der Göttin Artemis (diese Figur repräsentiert die Schutzgöttin der Stadt Ephesos und gilt als eine der wichtigsten Gottheiten der griechischen und römischen Welt);  (iii) Architekturfragmente (zu den Höhepunkten des Museums gehören auch die Überreste monumentaler Bauten, darunter Säulen, Kapitelle und Reliefs, die ursprünglich zu den großen öffentlichen Gebäuden und Tempeln von Ephesos gehörten);  sowie (iv) Alltagsgegenstände: (zahlreiche kleinere Funde, die das alltägliche Leben in der antiken Stadt veranschaulichen. Dazu gehören Keramiken, Münzen, Schmuck und Werkzeuge)"}, {"kategorie": "", "text": "Ephesos war eine bedeutende Stadt der griechischen und später römischen Antike, die im Westen der heutigen Türkei lag. Sie war ein wichtiges Handelszentrum und religiöses Zentrum der antiken Welt, insbesondere durch den Tempel der Artemis, der als eines der Sieben Weltwunder der Antike gilt. Die Ruinen von Ephesos zählen heute zu den bedeutendsten archäologischen Stätten der Welt."}]'::jsonb, ''),
  ('palaeae-salm', 'Palää Salm', '', '', '', '', 'Palais Salm', '[{"kategorie": "allg.", "text": "\"historisches Stadtpalais im 3. Wiener Bezirk ([[Landstraße]]) in der [[Salmgasse]] 2\""}, {"kategorie": "", "text": "Das Palais wurde im 18. Jahrhundert im Stil des Spätbarock für die Familie Salm-Reifferscheidt errichtet. Die Salms waren eine Adelsfamilie mit Wurzeln im Rheinland, die in der [[Habsburgermonarchie]] bedeutende politische und gesellschaftliche Positionen innehatten"}, {"kategorie": "", "text": "Die Fassade des Palais ist schlicht, aber elegant, mit einer klaren symmetrischen Anordnung der Fenster und einer dezenten Dekoration"}, {"kategorie": "", "text": "Das Gebäude ist von einem Innenhof umgeben, der typisch für Stadtpaläste dieser Epoche ist. Der Innenhof diente als privater Rückzugsort und war gleichzeitig ein repräsentativer Teil der Adelsresidenz"}, {"kategorie": "", "text": "Heute befindet sich das Palais Salm in Privatbesitz und hat keine öffentliche Funktion wie einige der bekannteren Stadtpalais in Wien. Es dient vorwiegend als Wohn- oder Geschäftshaus und hat in der Öffentlichkeit nicht die gleiche Bedeutung wie größere Palais, die museale oder kulturelle Funktionen übernommen haben."}]'::jsonb, ''),
  ('wiina-historismus', 'Wiina Historismus', '', '', '', '', 'Wiener Historismus', '[{"kategorie": "allg.", "text": "\"architektonische und kunstgeschichtliche Stilrichtung, die im 19. Jahrhundert in Europa aufkam\""}, {"kategorie": "", "text": "Er zeichnet sich dadurch aus, dass er auf frühere Epochen der Kunst- und Architekturgeschichte zurückgreift und diese Stilelemente in einem neuen Kontext vereint"}, {"kategorie": "", "text": "Der Historismus bediente sich einer Vielzahl von historischen Stilen wie Romanik, Gotik, Renaissance, Barock und [[Klassizismus]] und kombinierte sie teilweise zu neuen, eklektischen Kompositionen"}, {"kategorie": "", "text": "Eines der bekanntesten Beispiele für den Historismus ist die [[Wiener]] Ringstraße, die im späten 19. Jahrhundert angelegt wurde"}, {"kategorie": "", "text": "Die Gebäude entlang der Ringstraße, darunter das [[Parlament]] (im griechischen Klassizismus), das [[Rathaus]] (im neugotischen Stil) und die [[Universität]] Wien (im Neorenaissance-Stil), illustrieren den stilistischen Reichtum"}, {"kategorie": "", "text": "Der Eklektizismus des Historismus reflektierte den Wunsch nach repräsentativer Architektur, die sich bewusst auf die Vergangenheit bezieht."}]'::jsonb, ''),
  ('palaeae-schdahembeag', 'Palää Schdahembeag', '', '', '', '', 'Palais Starhemberg', '[{"kategorie": "allg.", "text": "\"historisches Stadtpalais am [[Minoritenplatz]] 5 im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Es ist einer der ältesten Barockpaläste Wiens und bildet neben dem Leopoldinischen Trakt der Hofburg das einzige Beispiel frühbarocker Palastarchitektur in Wien"}, {"kategorie": "", "text": "Das Palais wurde im 18. Jahrhundert für die Familie Starhemberg, eine der bedeutendsten Adelsfamilien des [[Habsburgerreiches]], erbaut. Die Familie Starhemberg war politisch und militärisch stark mit der Geschichte Wiens und Österreichs verbunden, insbesondere durch die Rolle von Ernst Rüdiger von Starhemberg, der als Verteidiger Wiens während der [[Zweiten]] Türkenbelagerung 1683 berühmt wurde"}, {"kategorie": "", "text": "Das Palais Starhemberg am Minoritenplatz wird heute als Verwaltungsgebäude genutzt. Seit 1970 Sitz des Bundesministeriums für Wissenschaft und Forschung beherbergt es heute das Bundesministerium für Unterricht, Kunst und Kultur."}]'::jsonb, ''),
  ('palaeae-mollard-clary', 'Palää Mollard-Clary', '', '', '', '', 'Palais Mollard-Clary', '[{"kategorie": "allg.", "text": "\"historisches Stadtpalais im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) in der [[Herrengasse]] 9\""}, {"kategorie": "", "text": "Das Palais wurde um 1686 im Auftrag von Graf Erasmus von Starhemberg erbaut, einem Mitglied der bekannten Adelsfamilie, die maßgeblich an der Verteidigung Wiens während der [[Zweiten]] Türkenbelagerung beteiligt war"}, {"kategorie": "", "text": "Im Jahr 1760 erwarb die Familie Mollard das Palais. Die Familie Mollard war eng mit dem Wiener Adel und dem Habsburgerhof verbunden. Das Palais wurde nach ihnen und später nach den Fürsten Clary-Aldringen benannt, die das Gebäude in der zweiten Hälfte des 18. Jahrhunderts erwarben"}, {"kategorie": "", "text": "Das Palais Mollard-Clary ist ein Beispiel für die barocke Architektur Wiens. Es verfügt über eine imposante Fassade, die durch ihre Symmetrie und Eleganz besticht"}, {"kategorie": "", "text": "Die Gestaltung des Innenhofes sowie die prächtigen Innenräume spiegeln den Glanz der Wiener Aristokratie des 17. und 18. Jahrhunderts wider. Ursprünglich diente das Palais als Residenz für Adlige, wurde aber später für verschiedene Zwecke genutzt"}, {"kategorie": "", "text": "Heute ist es bekannt als Sitz des [[Globenmuseums]] und des [[Esperantomuseums]], beides Teil der [[Österreichischen]] Nationalbibliothek."}]'::jsonb, ''),
  ('palaeae-liibn-auschbitz', 'Palää Liibn-Auschbitz', '', '', '', '', 'Palais Lieben-Auspitz', '[{"kategorie": "allg.", "text": "historisches Stadtpalais am Universitätsring im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), bekannt als Standort des [[Cafés]] Landtmann und des legendären [[literarischen]] Salons von Berta Zuckerkandl-Szeps (jüdisch-österreichische Schriftstellerin, Journalistin, Kritikerin und Salonnière)"}, {"kategorie": "", "text": "Es wurde im Auftrag der Geschwister Leopold, Adolf, Helene, Richard und Ida Lieben und ihres Cousins und Helenes Ehemann Rudolf Auspitz von den Architekten Carl Schumann und Ludwig Tischler 1873 bis 1874 im Stil des [[Historismus]] errichtet"}, {"kategorie": "", "text": "Die Familie Lieben war eine bekannte Bankiers- und Industriellenfamilie, die eine bedeutende Rolle in der Wirtschaft und im gesellschaftlichen Leben Wiens spielte. Die Familie Auspitz war ebenfalls sehr einflussreich und engagierte sich in der Wissenschaft und Wirtschaft. Beide Familien standen in engem Kontakt mit dem Wiener Hof und der Intellektuellenszene der Stadt"}, {"kategorie": "", "text": "Zu dieser Zeit war ein Großteil der Wiener Ringstraße noch in Bau: Als das Haus in Betrieb genommen wurde, bestand weder das heute benachbarte Hauptgebäude der [[Universität]] Wien noch das neue Haus des Burgtheaters"}, {"kategorie": "", "text": "Das Palais war ursprünglich ein repräsentatives Wohnhaus für die beiden Familien und spiegelte ihren Wohlstand und gesellschaftlichen Einfluss wider"}, {"kategorie": "", "text": "Das Palais Lieben-Auspitz ist ein typisches Beispiel für die Gründerzeitarchitektur, die Wien im späten 19. Jahrhundert prägte"}, {"kategorie": "", "text": "Die prunkvolle Fassade weist klassizistische Elemente auf, wie elegante Säulen und ornamentale Verzierungen. Das Gebäude ist in mehreren Stockwerken angelegt, die großzügige Wohnungen und Repräsentationsräume beherbergten"}, {"kategorie": "", "text": "Im Erdgeschoß befindet sich das bekannte [[Café]] Landtmann. Berta Zuckerkandl-Szeps veranstaltete in diesem Haus ihren literarischen Salon (Eingang [[Oppolzergasse]] 6)."}]'::jsonb, ''),
  ('literarischer-salon-von-berta-zuckerkandl-szeps', 'Literarischer Salon von Berta Zuckerkandl-Szeps', '', '', '', '', 'Literarischer Salon von Berta Zuckerkandl-Szeps', '[{"kategorie": "allg.", "text": "\"bedeutender Treffpunkt für Künstler, Schriftsteller, Intellektuelle und Politiker im Wien der späten [[Habsburgermonarchie]]\""}, {"kategorie": "", "text": "Der Salon wurde von der österreichischen Schriftstellerin, Journalistin und Kunstkritikerin Berta Zuckerkandl-Szeps geführt und spielte eine zentrale Rolle in der Wiener Moderne, der kulturellen Blütezeit der Stadt um die Wende vom 19. zum 20. Jahrhundert"}, {"kategorie": "", "text": "Der Salon fand hauptsächlich im Palais Lieben-Auspitz am Universitätsring 4 in Wien statt, das auch das berühmte [[Café]] Landtmann beherbergt"}, {"kategorie": "", "text": "In diesem Salon verkehrte die künstlerische und wissenschaftliche Elite des Landes, darunter Johann Strauss (Sohn), Gustav Klimt, Arthur Schnitzler, Max Reinhardt und Franz Theodor Csokor. Alma Mahler-Werfel lernte hier 1901 Gustav Mahler kennen"}, {"kategorie": "", "text": "Zudem nahm die Politik eine wichtige Rolle ein, und viele führende Denker und Diplomaten der Zeit suchten den Austausch in Zuckerkandls Salon. Sie förderte auch den kulturellen Austausch zwischen Österreich und Frankreich und hatte enge Beziehungen zu französischen Intellektuellen und Künstlern"}, {"kategorie": "", "text": "Nach dem Anschluss Österreichs an das [[Deutsche]] Reich 1938 musste Berta Zuckerkandl als Jüdin vor den Nationalsozialisten fliehen. Sie emigrierte nach Paris, wo sie bis zu ihrem Tod im Jahr 1945 lebte"}, {"kategorie": "", "text": "Der Salon wurde nie wieder in der gleichen Form belebt, doch sein Einfluss auf die Wiener Moderne und die europäische Kulturgeschichte bleibt unvergessen."}]'::jsonb, ''),
  ('cafe-landtmann', 'Café Landtmann', '', '', '', '', 'Café Landtmann', '[{"kategorie": "allg.", "text": "eines der bekanntesten und traditionsreichsten Kaffeehäuser Wiensam Universitätsring 4 im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) in unmittelbarer Nähe zum Wiener [[Rathaus]], dem [[Burgtheater]] und der [[Universität]] Wien"}, {"kategorie": "", "text": "Das Café wurde 1873 von Franz Landtmann eröffnet und entwickelte sich schnell zu einem der elegantesten Kaffeehäuser der Stadt. Es war ein Treffpunkt der gehobenen Wiener Gesellschaft und zog zahlreiche prominente Persönlichkeiten an"}, {"kategorie": "", "text": "Zu den berühmten Gästen des Café Landtmann zählten Größen wie der Psychoanalytiker Sigmund Freud, der Schriftsteller Peter Altenberg, der Dramatiker Arthur Schnitzler sowie der Komponist Gustav Mahler. Auch viele Politiker, darunter Bundeskanzler und Staatsmänner, nutzten das Café als Treffpunkt für informelle Gespräche"}, {"kategorie": "", "text": "Das Interieur des Café Landtmann wurde im Stil der Belle Époque gestaltet und besticht durch seine klassische, elegante Einrichtung. Die großen Spiegel, die Holzvertäfelungen und die traditionellen Marmortische verleihen dem Café eine zeitlose Atmosphäre, die den Charme des späten 19. und frühen 20. Jahrhunderts bewahrt"}, {"kategorie": "", "text": "Das Café Landtmann ist ein typisches Beispiel für die berühmte [[Wiener]] Kaffeehauskultur, die seit 2011 zum immateriellen Kulturerbe der UNESCO zählt. Es bietet einen Ort, an dem man stundenlang verweilen kann, um Kaffee zu trinken, Zeitungen zu lesen oder Gespräche zu führen."}]'::jsonb, ''),
  ('beamuda-dreiick', 'Beamuda-Dreiick', '', '', '', '', 'Bermuda-Dreieck', '[{"kategorie": "allg.", "text": "eines der bekanntesten Ausgehviertel der Stadt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), das sich in den Straßen rund um den [[Rabensteig]], den [[Schwedenplatz]] und den [[Donaukanal]] befindet"}, {"kategorie": "", "text": "Das Bermuda-Dreieck umfasst hauptsächlich die Straßen [[Rabensteig]], [[Seitenstettengasse]], [[Judengasse]] und Teile der [[Rotenturmstraße]]"}, {"kategorie": "", "text": "Diese Gegend ist Teil des historischen Wiener Jüdischen Viertels und gehört zu einem der ältesten Teile der Stadt. Viele der engen Gassen und Gebäude stammen aus dem Mittelalter"}, {"kategorie": "", "text": "Das Viertel ist bekannt für seine Bars, Clubs und Restaurants und hat sich zu einem der Haupttreffpunkte für das Nachtleben in der Wiener Innenstadt entwickelt"}, {"kategorie": "", "text": "Der Begriff Bermuda-Dreieck wurde in den 1970er Jahren von den Wienern geprägt und bezieht sich auf das berühmte Bermuda-Dreieck im Atlantik, wo Schiffe und Flugzeuge angeblich spurlos verschwinden. In Wien wird das Wort mit einem Augenzwinkern verwendet, da sich Menschen in den zahlreichen Lokalen „verlieren“ und die Zeit aus den Augen verlieren."}]'::jsonb, ''),
  ('schdodttempl-synagogn', 'Schdodttempl-Synagogn', '', '', '', '', 'Stadttempel-Synagoge', '[{"kategorie": "allg.", "text": "wichtigste Synagoge der Israelitischen Kultusgemeinde Wien (IKG), die sich in der [[Seitenstettengasse]] 4 im 1. Wiener Bezirk ([[Innere]] Stadt) befindet"}, {"kategorie": "", "text": "Sie ist die einzige von ursprünglich mehr als 90 Synagogen und Bethäusern in Wien, die die Novemberpogrome von 1938 (Reichskristallnacht) überstanden hat"}, {"kategorie": "", "text": "Der Stadttempel wurde zwischen 1825 und 1826 im Biedermeier-Stil erbaut und vom Architekten Josef Kornhäusel entworfen. Erbaut wurde er auf Grundlage eines kaiserlichen Dekrets, das vorsah, dass jüdische Gebetshäuser von außen nicht als solche erkennbar sein durften. Aus diesem Grund ist die Synagoge in einem Wohnblock eingebettet und von der Straße aus nicht direkt sichtbar. Man betritt sie über ein Innenhofportal, das nur zu bestimmten Zeiten geöffnet ist"}, {"kategorie": "", "text": "Während des Nationalsozialismus wurde die Stadttempel-Synagoge, anders als fast alle anderen Synagogen in Wien, nicht zerstört. Der Grund hierfür war ihre Nähe zu anderen Wohngebäuden, da eine Zerstörung oder Brandstiftung eine Gefahr für die Nachbargebäude dargestellt hätte"}, {"kategorie": "", "text": "Das Gebäude der Stadttempel-Synagoge folgt den Grundsätzen des Biedermeier-Stils, der Einfachheit und Eleganz verbindet. Der eigentliche Betsaal ist ein ovaler Raum, der von einer zentralen Kuppel überragt wird. Rund um den Hauptraum befinden sich hölzerne Galerien, die traditionell für die weiblichen Gemeindemitglieder reserviert sind, während die Männer im Erdgeschoss sitzen"}, {"kategorie": "", "text": "Im Inneren der Synagoge befindet sich der Torah-Schrein (Aron haKodesh), der das Zentrum des religiösen Lebens bildet. Der Schrein ist kunstvoll verziert und beherbergt die heiligen Torah-Rollen."}]'::jsonb, ''),
  ('ostarrichi-park', 'Ostarrichi-Park', '', '', '', '', 'Ostarrichi-Park', '[{"kategorie": "allg.", "text": "\"kleine, aber historisch bedeutende Grünfläche im 9. Wiener Bezirk ([[Alsergrund]]) direkt vor dem Gebäude der [[Österreichischen]] Nationalbank und nahe der [[Alser]] Straße\""}, {"kategorie": "", "text": "Der Name \"Ostarrichi\" leitet sich von der mittelalterlichen Bezeichnung Österreichs ab, die erstmals im Jahr 996 in einer Schenkungsurkunde erwähnt wurde. Dieser Name markiert die erste urkundliche Nennung des Gebietes, das später zu Österreich wurde"}, {"kategorie": "", "text": "Im Ostarrichipark befindet sich befindet sich die Shoah-Namensmauern-Gedenkstätte, die 2021 eingeweiht wurde"}, {"kategorie": "", "text": "Sie erinnert an die etwa 65.000 österreichischen Juden, die während der nationalsozialistischen Herrschaft in Konzentrationslagern und bei anderen Vernichtungsaktionen ermordet wurden"}, {"kategorie": "", "text": "Die Gedenkstätte besteht aus Mauern, auf denen die Namen der etwa 65.000 jüdischen Opfer der Shoah eingraviert sind. Diese Mauern sind in Form von großen Granitplatten angelegt, die die Namen der Ermordeten in alphabetischer Reihenfolge aufführen. Die schlichte und eindrucksvolle Gestaltung unterstreicht die Würde und Ernsthaftigkeit des Gedenkens an die Toten."}]'::jsonb, ''),
  ('goidanes-u', 'Goidanes U', '', '', '', '', 'Goldenes U', '[{"kategorie": "allg.", "text": "\"Bezeichnung für das exklusive Luxus-Einkaufsviertel im Herzen Wiens, das aus den drei bedeutendsten Einkaufsstraßen der Stadt besteht: dem [[Kohlmarkt]], dem [[Graben]] und der [[Kärntner]] Straße\""}, {"kategorie": "", "text": "Diese drei Straßen bilden zusammen eine Art U-förmige Struktur in der Wiener Innenstadt und gelten als die edelsten und prestigeträchtigsten Adressen für hochwertigen Einzelhandel und Luxusmarken in Österreich"}, {"kategorie": "", "text": "Das \"Goldene U\" ist die exklusivste Einkaufsgegend Wiens und zieht jährlich Millionen von Touristen sowie wohlhabende Kunden aus aller Welt an. Die Ansammlung von Luxusmarken, hochwertigen Einzelhandelsgeschäften und traditionsreichen Wiener Unternehmen macht das Viertel zu einem der wichtigsten Shopping-Destinationen in Mitteleuropa"}, {"kategorie": "", "text": "Neben dem Einkaufsangebot ist das \"Goldene U\" auch wegen seiner architektonischen Pracht und der Nähe zu wichtigen Sehenswürdigkeiten wie dem [[Stephansdom]], der [[Hofburg]] und der [[Wiener]] Staatsoper ein beliebter Ort zum Flanieren. Es bietet eine harmonische Kombination aus historischem Wiener Flair und modernem Luxus."}]'::jsonb, ''),
  ('groosse-schbealgossn', 'Groosse Schbealgossn', '', '', '', '', 'Große Sperlgasse', '[{"kategorie": "allg.", "text": "historische Straße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die sich im nördlichen Teil des Bezirks in der Nähe der [[Taborstraße]] und des [[Karmelitermarkts]] befindet"}, {"kategorie": "", "text": "Die Straße ist bekannt für ihre historische Bedeutung und für das dort befindliche Wiener [[Kriminalmuseum]]"}, {"kategorie": "", "text": "Die Große Sperlgasse liegt in einem Gebiet, das im 17. und 18. Jahrhundert stark urbanisiert wurde, als die [[Leopoldstadt]] wuchs und sich zu einem bedeutenden Teil Wiens entwickelte"}, {"kategorie": "", "text": "Sie ist benannt nach dem damals dort ansässigen Gasthaus und Vergnügungsetablissement \"Zum Sperl\" (2, Kleine Sperlgasse 2a und 2c) beziehungsweise dessen Besitzer Johann Georg Sperlbauer (volkstümlich \"Sperl\" genannt)"}, {"kategorie": "", "text": "In der jüdischen Geschichte Wiens spielt die Große Sperlgasse ebenfalls eine Rolle, da sie in einem Teil der Leopoldstadt liegt, der bis zur Verfolgung im Nationalsozialismus eine große jüdische Bevölkerung beherbergte. Während der Zeit des Nationalsozialismus wurde die jüdische Gemeinschaft in diesem Gebiet stark dezimiert, und viele Häuser, die zuvor jüdischen Familien gehörten, wurden enteignet"}, {"kategorie": "", "text": "Eine der bekanntesten Einrichtungen in der Großen Sperlgasse ist das Wiener Kriminalmuseum, das sich im Haus Nr. 24 befindet. Das Museum gibt einen detaillierten Überblick über die Kriminalgeschichte Wiens und zeigt Exponate aus verschiedenen Epochen der Verbrechensbekämpfung."}]'::jsonb, ''),
  ('haus-des-meeres', 'Haus des Meeres', '', '', '', '', 'Haus des Meeres', '[{"kategorie": "allg.", "text": "\"öffentliches Aquarium und Tropenhaus in Wien, das sich im [[Flakturm]] des [[Esterházyparks]] im 6. Wiener Gemeindebezirk ([[Mariahilf]]) befindet\""}, {"kategorie": "", "text": "Es ist eines der größten Aquarien in Österreich und beherbergt eine beeindruckende Vielfalt an Meerestieren, Reptilien, Amphibien und Vögeln"}, {"kategorie": "", "text": "Das Haus des Meeres wurde 1957 im ehemaligen Flakturm des Zweiten Weltkriegs im [[Esterházypark]] eröffnet. Der Flakturm, ein massiver Betonbunker, der ursprünglich als Luftabwehr- und Schutzbunker diente, wurde nach dem Krieg für zivile Zwecke umfunktioniert. Der Umbau zum Aquarium ermöglichte die Schaffung einer einzigartigen Ausstellungsumgebung für Meerestiere und Reptilien"}, {"kategorie": "", "text": "Das Haus des Meeres bietet auf mehreren Etagen eine Vielzahl von Themenbereichen und Exponaten, darunter (i) Meerwasseraquarien, (ii) frei umherlaufende Vögel, Affen und Reptilien in einer nachgebildeten Tropenlandschaft (\"Tropenhaus\"), (iii) verschiedene Krokodilarten und andere Reptilien in einer naturnah gestalteten Umgebung (\"Krokodilpark\"), sowie (iv) zahlreiche Terrarien mit Schlangen, Geckos, Fröschen und sonstigen Amphibien und Reptilien"}, {"kategorie": "", "text": "Ein besonderes Highlight des Hauses des Meeres ist die Aussichtsplattform auf dem Dach des Flakturms. Von hier aus haben Besucher einen 360-Grad-Panoramablick über Wien"}, {"kategorie": "", "text": "Der Kontrast zwischen der historischen Architektur des Flakturms und der modernen Nutzung als Aquarium und Aussichtsplattform macht das Haus des Meeres zu einem einzigartigen Wahrzeichen Wiens."}]'::jsonb, ''),
  ('gruena-beag', 'Grüna Beag', '', '', '', '', 'Grüner Berg', '[{"kategorie": "allg.", "text": "Anhöhe zwischen dem 13. Wiener Gemeindebezirk ([[Hietzing]]) und dem 12. Wiener Gemeindebezirk ([[Meidling]]), die sich in der Nähe des Schönbrunner Schlossparks befindet"}, {"kategorie": "", "text": "Seinen Namen erhielt der \"Grüne Berg\" durch Josef Freiherr von Hagenmüller zu Grünberg, einem Gerichtsadvokaten. Dieser erbaute um 1790 auf dem Hügel mehrere Häuser, die unter dem Namen Grünbergsiedlung bekannt wurden"}, {"kategorie": "", "text": "Über den Grünen Berg führt eine der wichtigsten Verkehrsadern in diesem Teil Wiens, die [[Grünbergstraße]]"}, {"kategorie": "", "text": "Diese verläuft in nord-südlicher Richtung und verbindet das Wiental (B 1) über die [[Altmannsdorfer]] Straße mit der [[Südosttangente]] (A 23) bzw. der Süd Autobahn (A 2)"}, {"kategorie": "", "text": "Der Grüne Berg ist zudem eine historisch bedeutsame Anhöhe, die in der Vergangenheit Teil des kaiserlichen Jagdgebiets rund um Schönbrunn war."}]'::jsonb, ''),
  ('launge-gossn', 'Launge Gossn', '', '', '', '', 'Lange Gasse', '[{"kategorie": "allg.", "text": "\"traditionsreiche und zugleich moderne Straße im 8. Wiener Bezirk ([[Josefstadt]]), die sich von der [[Lerchenfelder]] Straße im Süden bis zur [[Alser]] Straße im Norden erstreckt\""}, {"kategorie": "", "text": "Der Name \"Lange Gasse\" ist historisch bedingt und leitet sich von der ursprünglich ausgedehnten Länge der Straße ab. Im Mittelalter führte die Lange Gasse als eine der wichtigsten Verbindungswege aus der Stadt Wien heraus in die nördlichen Vororte"}, {"kategorie": "", "text": "Entlang der Lange Gasse sind viele Gebäude aus der [[Gründerzeit]] und dem 19. Jahrhundert zu finden, was den historischen Charakter der Straße prägt. Viele der Wohnhäuser besitzen die für Wien typischen verzierenden Fassaden, die zur Gründerzeit errichtet wurden"}, {"kategorie": "", "text": "Bedeutende Einrichtungen in der Nähe sind das [[Theater]] in der Josefstadt, das [[Alte]] AKH und die Piaristenkirche [[Maria]] Treu."}]'::jsonb, ''),
  ('meidlinga-friidhof', 'Meidlinga Friidhof', '', '', '', '', 'Meidlinger Friedhof', '[{"kategorie": "", "text": "Der Friedhof ist 130.331 Quadratmeter groß, verfügt über rund 17.230 Grabstellen und besteht aus zwei Teilen, die durch die [[Eibesbrunnergasse]] getrennt werden, wo sich auch zwei weitere Eingänge befinden"}, {"kategorie": "", "text": "Im alten Teil dominieren die typischen prunkvollen Grüfte der Meidlinger Bürgerschaft aus der Zeit um die Jahrhundertwende. Hinter der Aufbahrungshalle gelangt man zum ältesten Teil, einer Allee aus verfallen klassizistischen Gräbern, die von zwei Engelsskulpturen flankiert wird. Hier befinden sich die zwei Mausoleen berühmter Wiener Familien: die Sommaruga-Gruft mit dem Grab der Louise Ulrike von Sommaruga und die Gruft der Familie Miller von Aichholz. Ferner ruht hier der Schulreformer Otto Glöckel in einem Ehrengrab"}, {"kategorie": "", "text": "Der neue Teil wartet mit prachtvollen Grüften im [[Jugendstil]] auf. Hier befinden sich vorwiegend Gräber des Kleinbürgertums"}, {"kategorie": "", "text": "Der Meidlinger Friedhof gilt als einer der ältesten Friedhöfe Wiens, die heute noch benutzt werden. Der ursprüngliche Meidlinger Friedhof wurde 1784 an der Stelle der heutigen Vierthalergasse 11 angelegt, musste aber bereits 1806 wegen Wassereinbrüchen wieder aufgegeben werden"}, {"kategorie": "", "text": "Anschließend stellte der Bürger Johann Putz ein Grundstück zur Verfügung, das in der Nähe der heutigen Straßenzüge Sechtergasse, Pachmüllergasse und Zeleborgasse lag. Dieser zweite Friedhof wurde 1807 eingeweiht"}, {"kategorie": "", "text": "Aufgrund der Choleraseuche und der wachsenden Bevölkerung in Meidling musste der Friedhof mehrmals erweitert werden, zunächst 1831 und nochmals 1859. Schließlich war auch dieser Platz nicht ausreichend, und der Friedhof wurde schließlich auf ein weiter außerhalb liegendes Gebiet nahe dem heutigen [[Meidlinger]] Bahnhof verlegt"}, {"kategorie": "", "text": "Der neue Meidlinger Friedhof wurde mehrfach erweitert und erhielt im Jahr 1927 eine Urnennischenanlage, um den wachsenden Bedürfnissen der Bestattungen gerecht zu werden"}, {"kategorie": "", "text": "Trotz Plänen, den Friedhof 1953 zu schließen, blieb er in Betrieb, da sich die Bevölkerung gegen die Schließung aussprach. Besonders prägend war die Volksabstimmung 1980, bei der sich 63,2 Prozent der Wähler für den Erhalt des Friedhofs aussprachen"}, {"kategorie": "", "text": "Eine Besonderheit ist das Denkmal für die Opfer des 12. Februar 1934, das im Urnenhain am 12. Februar 1954 für zwei Teilnehmer der [[Februarkämpfe]] von 1934 enthüllt."}]'::jsonb, ''),
  ('aum-fasangoatn', 'Aum Fasangoatn', '', '', '', '', 'Am Fasangarten', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Bezirk ([[Hietzing]]), die sich in der Nähe des [[Schlossparks]] Schönbrunn befindet\""}, {"kategorie": "", "text": "Der Name der Straße leitet sich von den historischen Fasangärten ab, die südlich des Schlossparks angelegt wurden, um Fasanen für die kaiserliche Jagd zu züchten"}, {"kategorie": "", "text": "Am Fasangarten befindet sich auch die [[Maria-Theresien-Kaserne]], eine der wichtigsten militärischen Einrichtungen Wiens"}, {"kategorie": "", "text": "Die Straße Am Fasangarten ist eine ruhige Wohnstraße, die überwiegend von Villen und gehobenen Wohnhäusern gesäumt ist. Die Umgebung ist bekannt für ihre grüne und gepflegte Atmosphäre, die eine hohe Lebensqualität bietet."}]'::jsonb, ''),
  ('maria-theresiin-kasean', 'Maria-Theresiin-Kasean', '', '', '', '', 'Maria-Theresien-Kaserne', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Bezirk ([[Hietzing]]), welche die Stadtteile [[Hetzendorf]], [[Lainz]] und [[Speising]] miteinander verbindet\""}, {"kategorie": "", "text": "Der Name \"Fasangartenstraße\" verweist auf die Fasangärten, die in der Umgebung des Schlosses Schönbrunn zur Zucht von Fasanen angelegt wurden. Diese Gärten hatten in der Zeit des [[Habsburgerreichs]] eine wichtige Funktion für die königliche Jagd und die Versorgung des Hofes. Die Nähe zur kaiserlichen Residenz Schloss Schönbrunn gibt der Straße und dem umliegenden Viertel eine besondere historische Bedeutung."}, {"kategorie": "", "text": "Die Fasangartenstraße liegt in einer gehobenen Wohngegend, die besonders für ihre ruhige und grüne Umgebung geschätzt wird"}, {"kategorie": "", "text": "Nördlich der Fasangartenstraße befinden sich die [[Maria-Thersien-Kaserne]] und der [[Schlosspark]] Schönbrunn, südlich von ihr liegt der [[Hetzendorfer]] Friedhof."}]'::jsonb, ''),
  ('schoenbrunna-allee', 'Schönbrunna Allee', '', '', '', '', 'Schönbrunner Allee', '[{"kategorie": "allg.", "text": "ruhige Wohnstraße im 12. und 13. Wiener Bezirk ([[Meidling]] und [[Hietzing]]), welche die [[Hetzendorferstraße]] im Süden mit der [[Grünbergstraße]] im Norden verbindet"}, {"kategorie": "", "text": "Die Schönbrunner Allee hat ihre Wurzeln in der Zeit des [[Habsburgerreichs]], als sie als Zufahrtsweg zum kaiserlichen Schloss Schönbrunn genutzt wurde. Das Schloss war eine Sommerresidenz der Habsburger und spielte eine zentrale Rolle im höfischen Leben der Monarchie. Die Allee diente den Mitgliedern des Hofes, auswärtigen Gästen und anderen Adeligen als direkte Verbindung zum Schloss"}, {"kategorie": "", "text": "Die Schönbrunner Allee wurde seinerzeit als direkte Verbindung vom [[Schloss]] Hetzendorf zum [[Schloss]] Schönbrunn angelegt"}, {"kategorie": "", "text": "Sie liegt heute in einer ruhigen und gehobenen Wohngegend, die von grünen Parks, Gärten und historischen Gebäuden geprägt ist."}]'::jsonb, ''),
  ('wuehoemsduafa-park', 'Wühömsduafa Park', '', '', '', '', 'Wilhelmsdorfer Park', '[{"kategorie": "allg.", "text": "\"eine der wenigen Grünflächen im dichtverbauten 12. Wiener Gemeindebezirk ([[Meidling]])\""}, {"kategorie": "", "text": "Der Park wurde benannt nach der früher hier befindlichen Vorortegemeinde [[Wilhelmsdorf]], die nur vier Jahre lang (1846-1850) Bestand hatte und seit 1851 zu [[Meidling]] gehört"}, {"kategorie": "", "text": "Der Wilhelmsdorfer Park, auch als Deckerpark bekannt, wurde 1990 neu gestaltet. Bereits seit 1909 bestand hier eine kleine öffentliche Grünfläche. Ein Schienenlager der Wiener Linien wurde um 1980 aufgelassen und wurde Bestandteil des Wilhelmsdorfer Parks"}, {"kategorie": "", "text": "Der Park zeichnet sich durch seinen alten Baumbestand aus und bietet auch ruhige Sitzecken, besonders im südöstlichen Teil. Das für Wiener Parks eher ungewöhnliche Farbkonzept in unterschiedlichen Blautönen soll diesen auch im Winter anziehend machen."}]'::jsonb, ''),
  ('unta-meidlinga-schdrossn', 'Unta-Meidlinga-Schdrossn', '', '', '', '', 'Unter-Meidlinger-Straße', '[{"kategorie": "allg.", "text": "Nebenstraße, die in Ost-West-Richtung verläuft und die Wiener Gemeindebezirke [[Favoriten]] (10. Bezirk) und [[Meidling]] (12. Bezirk) miteinander verbindet"}, {"kategorie": "", "text": "Sie wurde 1905 nach der ehemaligen Vorortgemeinde [[Untermeidling]] benannt, die den stadtzentrumsnäheren Teil des historischen Ortes Meidling umfasste und vom [[Wiental]] bis hierher reichte"}, {"kategorie": "", "text": "Untermeidling liegt südlich des [[Wienflusses]] im Nordosten von Meidling. Im Nordosten grenzt Untermeidling an den Bezirksteil [[Gaudenzdorf]], im Süden an den Bezirksteil [[Altmannsdorf]] und im Westen an den Bezirksteil [[Obermeidling]]"}, {"kategorie": "", "text": "Heute verläuft die \"Unter-Meidlinger-Straße\" durch ein dicht besiedeltes, lebendiges Wohn- und Geschäftsgebiet, in dem es viele Wohnanlagen, Schulen, Einkaufsmöglichkeiten und öffentliche Einrichtungen gibt."}]'::jsonb, ''),
  ('hetznduafa-friidhof', 'Hetznduafa Friidhof', '', '', '', '', 'Hetzendorfer Friedhof', '[{"kategorie": "", "text": "Der Friedhof liegt an der [[Elisabethallee]] in der Nähe des Schlosses Hetzendorf und dient als lokale Begräbnisstätte für die Bewohner der Umgebung. Obwohl er vergleichsweise klein ist, hat er durch seine Lage in einem historischen Teil Wiens und seine gepflegte Anlage eine besondere Bedeutung für den Bezirk"}, {"kategorie": "", "text": "Der Friedhof ist 7.622 Quadratmeter groß, verfügt über rund 1.000 Grabstellen und weist einige schlichte klassizistische Adelsgrüfte auf. Die bemerkenswerteste Grabstelle auf dem kleinen und stimmungsvollen Friedhof ist das Familiengrab der adeligen Familie von Dumreicher-Österreicher. Es stammt aus der Zeit um 1847 und ist in der Form einer dreiteiligen Neorenaissance-Ädikula gestaltet"}, {"kategorie": "", "text": "Auf dem Hetzendorfer Friedhof befinden sich die Ehrengräber von Franz Martin Schindler (römisch-katholischer Geistlicher, Moraltheologe, Kirchenrechtler und Politiker, 1847-1922) und Margarete Seemann (Wiener Roman-, Kinder- und Jugendbuchautorin, 1893-1949)."}]'::jsonb, ''),
  ('guadhaeu-schoda-gossn', 'Guadhäu-Schoda-Gossn', '', '', '', '', 'Gutheil-Schoder-Gasse', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrs- und Gewerbestraße im 23. Wiener Bezirk ([[Liesing]]), die nach der berühmten österreichischen Opernsängerin und Opernregisseurin Marie Gutheil-Schoder (1874–1935) benannt wurde\""}, {"kategorie": "", "text": "Marie Gutheil-Schoder war eine der führenden Sopranistinnen ihrer Zeit und trat auf den großen Bühnen Europas, insbesondere auch an der Wiener Staatsoper, auf. Sie war auch eine der ersten Frauen, die als Opernregisseurin tätig war und hat die Opernszene in Wien maßgeblich beeinflusst"}, {"kategorie": "", "text": "Die Gutheil-Schoder-Straße verläuft durch ein Gewerbegebiet im Süden Wiens, verbindet verschiedene wichtige Verkehrsachsen miteinander (wie die [[Eibesbrunnergasse]] mit der [[Anton-Baumgartner-Straße]]) und begrenzt im Westen den [[Draschepark]]"}, {"kategorie": "", "text": "Die Gutheil-Schoder-Gasse ist von Industrie-, Gewerbe- und Bürogebäuden geprägt, da sie in einem der größten Gewerbegebiete im Süden Wiens liegt. Entlang der Straße befinden sich Logistikzentren, Bürogebäude, Autohäuser und verschiedene Handelsunternehmen."}]'::jsonb, ''),
  ('anton-baumgoatna-schdrossn', 'Anton-Baumgoatna-Schdrossn', '', '', '', '', 'Anton-Baumgartner-Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsachse im 23. Wiener Gemeindebezirk ([[Liesing]]), die sowohl durch Wohn- als auch Gewerbegebiete führt\""}, {"kategorie": "", "text": "Sie verbindet die Stadtteile [[Inzersdorf]], [[Erlaa]] und [[Atzgersdorf]] miteinander und bietet eine gute Anbindung an das öffentliche Verkehrsnetz sowie an den Individualverkehr im Süden Wiens"}, {"kategorie": "", "text": "Die Straße ist nach dem nach dem Gemeinderat von Erlaa, Ökonomierat Anton Baumgartner (1858-1932) benannt, der sich in der ersten Hälfte des 20. Jahrhunderts um die Stadtentwicklung verdient gemacht hat"}, {"kategorie": "", "text": "Ein besonderes Merkmal der Anton-Baumgartner-Straße ist die Nähe zur [[Wohnhausanlage]] Alterlaa, einer der größten und bekanntesten Wohnanlagen Wiens, die auch aufgrund ihrer markanten Architektur und der hohen Lebensqualität in der Stadt bekannt ist."}]'::jsonb, ''),
  ('wohnhausaunlog-oiderlaa', 'Wohnhausaunlog Oiderlaa', '', '', '', '', 'Wohnhausanlage Alterlaa', '[{"kategorie": "allg.", "text": "\"eine der größten und bekanntesten Wohnsiedlungen in Wien, die im 23. Wiener Gemeindebezirk ([[Liesing]]) an der [[Anton-Baumgartner-Straße]] liegt\""}, {"kategorie": "", "text": "Sie wurde zwischen 1973 und 1985 nach den Plänen des Architekten Harry Glück errichtet und ist durch ihre markante Architektur und ihre umfangreichen Infrastruktureinrichtungen bekannt"}, {"kategorie": "", "text": "Die Wohnhausanlage gehört zu den bedeutendsten Projekten des sozialen Wohnbaus in Wien und bietet Wohnraum für mehrere tausend Menschen"}, {"kategorie": "", "text": "Sie besteht aus insgesamt 3 großen Wohnkomplexen, die sich durch ihre auffällige Terrassenbauweise und die markante Höhenstaffelung auszeichnen. Die Gebäude sind in Terrassen angelegt, wobei jede Wohnung einen großzügigen Balkon oder eine Terrasse bietet, die oft begrünt und als Freiraum genutzt wird. Diese Bauweise ist ein charakteristisches Merkmal des Architekten Harry Glück, der es sich zum Ziel setzte, hohe Lebensqualität und soziale Durchmischung im urbanen Wohnbau zu ermöglichen"}, {"kategorie": "", "text": "Die Wohnblöcke sind bis zu 27 Stockwerke hoch und bieten etwa 3.200 Wohnungen und eine Vielzahl von Gemeinschaftseinrichtungen (wie z.B. Schwimmbäder auf den Dächern der Wohngebäude)"}, {"kategorie": "", "text": "Die Wohnhausanlage Alterlaa bietet den Bewohnern eine umfassende Infrastruktur, die es ermöglicht, viele tägliche Erledigungen direkt innerhalb der Anlage zu erledigen. Es gibt eine Einkaufsstraße, die eine Vielzahl von Geschäften, Supermärkten, Restaurants und Dienstleistern beherbergt, sowie auch Kindergärten, Schulen und Gemeinschaftsräume, die den sozialen Zusammenhalt in der Siedlung fördern."}]'::jsonb, ''),
  ('grooss-wiin', 'Grooss-Wiin', '', '', '', '', 'Groß-Wien', '[{"kategorie": "allg.", "text": "\"geografische Bezeichnung, die zu verschiedenen Zeiten im Zusammenhang mit den Wiener Stadterweiterungen verwendet wurde\""}, {"kategorie": "", "text": "Die Bezeichnung \"Groß-Wien\" wurde erstmals im Zuge der Eingemeindung der Vororte (Gesetz von 19. Dezember 1890, Inkrafttreten 1. Jänner 1892) geprägt, wonach Wien fortan erstmals 19 Gemeindebezirke umfasste"}, {"kategorie": "", "text": "Von den Nationalsozialisten wurde die Bezeichnung übernommen, als sie am 15. Oktober 1938 Wien durch die Eingemeindung von 97 niederösterreichischen Ortsgemeinden zu einer Stadt mit 26 (zuvor 21) Gemeindebezirken erweiterten"}, {"kategorie": "", "text": "\"Groß-Wien\" umfasste damals rund 1.215 Quadratkilometer mit 2.087.000 Personen. Die Erweiterung hing einerseits mit Kriegsvorbereitungen, andererseits mit geplanten Infrastrukturprojekten zusammen"}, {"kategorie": "", "text": "Der Begriff „Groß-Wien“ wird heute vor allem benutzt, um das durch die Eingemeindungen während der NS-Zeit vergrößerte Wien von der heutigen Stadt zu unterscheiden, denn in der Besatzungszeit wurde 1954 der größere Teil dieser Erweiterungen wieder rückgängig gemacht."}]'::jsonb, ''),
  ('februarkaempfe-von-1934', 'Februarkämpfe von 1934', '', '', '', '', 'Februarkämpfe von 1934', '[{"kategorie": "allg.", "text": "\"bewaffneter Aufstand in Österreich, der im Februar 1934 stattfand und die Auseinandersetzung zwischen der austrofaschistischen Regierung unter Engelbert Dollfuß und der Arbeiterbewegung darstellte, die von der Sozialdemokratischen Arbeiterpartei (SDAP) und den ihr nahestehenden [[Republikanischen]] Schutzbund unterstützt wurde\""}, {"kategorie": "", "text": "Diese Kämpfe markierten das Ende der [[Ersten]] Republik und führten zur Errichtung eines autoritären, austrofaschistischen Ständestaates"}, {"kategorie": "", "text": "Die politische Lage in Österreich war in den frühen 1930er Jahren stark polarisiert. Auf der einen Seite standen die konservativen Kräfte, die von der Christlichsozialen Partei und der Regierung Dollfuß vertreten wurden, die 1933 das Parlament ausgeschaltet und eine autoritäre Herrschaft errichtet hatten"}, {"kategorie": "", "text": "Auf der anderen Seite stand die Arbeiterbewegung, die von der SDAP und ihrer paramilitärischen Organisation, dem [[Republikanischen]] Schutzbund, unterstützt wurde. Die zunehmende Spannung zwischen diesen Gruppen führte zu einem Konflikt um die Zukunft des Landes"}, {"kategorie": "", "text": "Am 12. Februar 1934 eskalierte die Situation, als es in Linz zu einem ersten Gefecht zwischen der Polizei und dem Republikanischen Schutzbund kam. Dieser Vorfall löste einen landesweiten Aufstand aus, in dem die sozialistische Arbeiterbewegung gegen die Regierungstruppen kämpfte. Die Kämpfe breiteten sich rasch auf andere Städte und Regionen aus, darunter Wien, Steyr, Graz, Kapfenberg und Bruck an der Mur"}, {"kategorie": "", "text": "In Wien kam es zu erbitterten Kämpfen in den [[Gemeindebauten]], den großen Wohnanlagen, die von der sozialistischen Stadtregierung errichtet worden waren und als Hochburgen der Arbeiterbewegung galten. Besonders bekannt wurden die Kämpfe im [[Karl-Marx-Hof]]"}, {"kategorie": "", "text": "Nach vier Tagen intensiver Kämpfe konnte die Regierung die Aufständischen weitgehend besiegen. Der Schutzbund war zahlenmäßig unterlegen und schlecht bewaffnet im Vergleich zu den staatlichen Truppen. Am 15. Februar 1934 endeten die Kämpfe mit der Niederlage des Republikanischen Schutzbundes und der sozialistischen Bewegung"}, {"kategorie": "", "text": "Die Folgen der Februarkämpfe waren dramatisch: Tausende von Menschen wurden getötet, verwundet oder verhaftet. Zahlreiche führende sozialistische Politiker wurden verhaftet oder hingerichtet, und die SDAP wurde verboten. Die Arbeiterbewegung in Österreich wurde stark geschwächt, und viele ihrer Anhänger flohen ins Ausland oder gingen in den Untergrund"}, {"kategorie": "", "text": "Nach den Kämpfen errichtete die Regierung Dollfuß den austrofaschistischen Ständestaat, eine autoritäre Diktatur, die bis zum Anschluss Österreichs an Nazi-Deutschland im Jahr 1938 bestehen blieb."}]'::jsonb, 'Easchde Republik'),
  ('februaraufstaund-von-1934', 'Februaraufstaund von 1934', '', '', '', '', 'Februaraufstand von 1934', '[{"kategorie": "allg.", "text": "\"bewaffneter Aufstand in Österreich, der im Februar 1934 stattfand und die Auseinandersetzung zwischen der austrofaschistischen Regierung unter Engelbert Dollfuß und der Arbeiterbewegung darstellte, die von der Sozialdemokratischen Arbeiterpartei (SDAP) und den ihr nahestehenden [[Republikanischen]] Schutzbund unterstützt wurde\""}, {"kategorie": "", "text": "Diese Kämpfe markierten das Ende der [[Ersten]] Republik und führten zur Errichtung eines autoritären, austrofaschistischen Ständestaates"}, {"kategorie": "", "text": "Die politische Lage in Österreich war in den frühen 1930er Jahren stark polarisiert. Auf der einen Seite standen die konservativen Kräfte, die von der Christlichsozialen Partei und der Regierung Dollfuß vertreten wurden, die 1933 das Parlament ausgeschaltet und eine autoritäre Herrschaft errichtet hatten"}, {"kategorie": "", "text": "Auf der anderen Seite stand die Arbeiterbewegung, die von der SDAP und ihrer paramilitärischen Organisation, dem [[Republikanischen]] Schutzbund, unterstützt wurde. Die zunehmende Spannung zwischen diesen Gruppen führte zu einem Konflikt um die Zukunft des Landes"}, {"kategorie": "", "text": "Am 12. Februar 1934 eskalierte die Situation, als es in Linz zu einem ersten Gefecht zwischen der Polizei und dem Republikanischen Schutzbund kam. Dieser Vorfall löste einen landesweiten Aufstand aus, in dem die sozialistische Arbeiterbewegung gegen die Regierungstruppen kämpfte. Die Kämpfe breiteten sich rasch auf andere Städte und Regionen aus, darunter Wien, Steyr, Graz, Kapfenberg und Bruck an der Mur"}, {"kategorie": "", "text": "In Wien kam es zu erbitterten Kämpfen in den [[Gemeindebauten]], den großen Wohnanlagen, die von der sozialistischen Stadtregierung errichtet worden waren und als Hochburgen der Arbeiterbewegung galten. Besonders bekannt wurden die Kämpfe im [[Karl-Marx-Hof]]"}, {"kategorie": "", "text": "Nach vier Tagen intensiver Kämpfe konnte die Regierung die Aufständischen weitgehend besiegen. Der Schutzbund war zahlenmäßig unterlegen und schlecht bewaffnet im Vergleich zu den staatlichen Truppen. Am 15. Februar 1934 endeten die Kämpfe mit der Niederlage des Republikanischen Schutzbundes und der sozialistischen Bewegung"}, {"kategorie": "", "text": "Die Folgen der Februarkämpfe waren dramatisch: Tausende von Menschen wurden getötet, verwundet oder verhaftet. Zahlreiche führende sozialistische Politiker wurden verhaftet oder hingerichtet, und die SDAP wurde verboten. Die Arbeiterbewegung in Österreich wurde stark geschwächt, und viele ihrer Anhänger flohen ins Ausland oder gingen in den Untergrund"}, {"kategorie": "", "text": "Nach den Kämpfen errichtete die Regierung Dollfuß den austrofaschistischen Ständestaat, eine autoritäre Diktatur, die bis zum Anschluss Österreichs an Nazi-Deutschland im Jahr 1938 bestehen blieb."}]'::jsonb, ''),
  ('buergerkriig-von-1934', 'Bürgerkriig von 1934', '', '', '', '', 'Bürgerkrieg von 1934', '[{"kategorie": "allg.", "text": "\"bewaffneter Aufstand in Österreich, der im Februar 1934 stattfand und die Auseinandersetzung zwischen der austrofaschistischen Regierung unter Engelbert Dollfuß und der Arbeiterbewegung darstellte, die von der Sozialdemokratischen Arbeiterpartei (SDAP) und den ihr nahestehenden [[Republikanischen]] Schutzbund unterstützt wurde\""}, {"kategorie": "", "text": "Diese Kämpfe markierten das Ende der [[Ersten]] Republik und führten zur Errichtung eines autoritären, austrofaschistischen Ständestaates"}, {"kategorie": "", "text": "Die politische Lage in Österreich war in den frühen 1930er Jahren stark polarisiert. Auf der einen Seite standen die konservativen Kräfte, die von der Christlichsozialen Partei und der Regierung Dollfuß vertreten wurden, die 1933 das Parlament ausgeschaltet und eine autoritäre Herrschaft errichtet hatten"}, {"kategorie": "", "text": "Auf der anderen Seite stand die Arbeiterbewegung, die von der SDAP und ihrer paramilitärischen Organisation, dem [[Republikanischen]] Schutzbund, unterstützt wurde. Die zunehmende Spannung zwischen diesen Gruppen führte zu einem Konflikt um die Zukunft des Landes"}, {"kategorie": "", "text": "Am 12. Februar 1934 eskalierte die Situation, als es in Linz zu einem ersten Gefecht zwischen der Polizei und dem Republikanischen Schutzbund kam. Dieser Vorfall löste einen landesweiten Aufstand aus, in dem die sozialistische Arbeiterbewegung gegen die Regierungstruppen kämpfte. Die Kämpfe breiteten sich rasch auf andere Städte und Regionen aus, darunter Wien, Steyr, Graz, Kapfenberg und Bruck an der Mur"}, {"kategorie": "", "text": "In Wien kam es zu erbitterten Kämpfen in den [[Gemeindebauten]], den großen Wohnanlagen, die von der sozialistischen Stadtregierung errichtet worden waren und als Hochburgen der Arbeiterbewegung galten. Besonders bekannt wurden die Kämpfe im [[Karl-Marx-Hof]]"}, {"kategorie": "", "text": "Nach vier Tagen intensiver Kämpfe konnte die Regierung die Aufständischen weitgehend besiegen. Der Schutzbund war zahlenmäßig unterlegen und schlecht bewaffnet im Vergleich zu den staatlichen Truppen. Am 15. Februar 1934 endeten die Kämpfe mit der Niederlage des Republikanischen Schutzbundes und der sozialistischen Bewegung"}, {"kategorie": "", "text": "Die Folgen der Februarkämpfe waren dramatisch: Tausende von Menschen wurden getötet, verwundet oder verhaftet. Zahlreiche führende sozialistische Politiker wurden verhaftet oder hingerichtet, und die SDAP wurde verboten. Die Arbeiterbewegung in Österreich wurde stark geschwächt, und viele ihrer Anhänger flohen ins Ausland oder gingen in den Untergrund"}, {"kategorie": "", "text": "Nach den Kämpfen errichtete die Regierung Dollfuß den austrofaschistischen Ständestaat, eine autoritäre Diktatur, die bis zum Anschluss Österreichs an Nazi-Deutschland im Jahr 1938 bestehen blieb."}]'::jsonb, ''),
  ('easchde-republik', 'Easchde Republik', '', '', '', '', 'Erste Republik', '[{"kategorie": "allg.", "text": "\"erste demokratische Staatsform in Österreich, die von 1918 bis 1934 bestand\""}, {"kategorie": "", "text": "Sie wurde nach dem Ende der [[Habsburgermonarchie]] und dem Zusammenbruch des Österreichisch-Ungarischen Reiches im Zuge des Ersten Weltkriegs gegründet. Die Republik ging damals durch eine schwierige Phase der politischen und wirtschaftlichen Instabilität, die schließlich mit der Errichtung einer autoritären Regierung im Jahr 1934 endete (siehe [[Februarkämpfe von 1934]])"}, {"kategorie": "", "text": "Die Erste Republik wurde am 12. November 1918 offiziell ausgerufen, nachdem der österreichische Kaiser [[Karl]] I. am 11. November 1918 auf die Ausübung seiner Regierungsfunktionen verzichtet hatte, ohne formell abzudanken. Dies markierte das Ende der Habsburgerherrschaft und der Monarchie in Österreich"}, {"kategorie": "", "text": "Die Ausrufung der Republik erfolgte in Wien durch die Provisorische Nationalversammlung der deutschsprachigen Teile des ehemaligen [[Habsburgerreichs]]. Die neue Republik umfasste die Gebiete des heutigen Österreich, die mehrheitlich von Deutschsprachigen bewohnt wurden, sowie das Sudetenland"}, {"kategorie": "", "text": "Die Verfassung von 1920, die als demokratische Grundlage der Ersten Republik diente, schuf eine parlamentarische Demokratie mit einem Präsidenten als Staatsoberhaupt und einem Parlament, das aus dem Nationalrat und dem Bundesrat bestand. Die Verfassung wurde von Karl Renner, dem führenden Sozialdemokraten, und Michael Mayr, einem Vertreter der Christlichsozialen, ausgearbeitet und trat 1920 in Kraft."}]'::jsonb, ''),
  ('zweite-republik', 'Zweite Republik', '', '', '', '', 'Zweite Republik', '[{"kategorie": "allg.", "text": "\"jene Staatsform Österreichs, die nach dem Zweiten Weltkrieg im Jahr 1945 begründet wurde und bis heute besteht\""}, {"kategorie": "", "text": "Sie bezeichnet die Wiedererrichtung einer demokratischen Republik nach der Zeit des Nationalsozialismus und dem [[Anschluss]] Österreichs an das [[Deutsche]] Reich im Jahr 1938"}, {"kategorie": "", "text": "Die Zweite Republik wird als direkte Nachfolgerin der [[Ersten]] Republik betrachtet, die von 1918 bis 1934 bestand, bevor sie durch ein autoritäres Regime und später durch den Nationalsozialismus abgelöst wurde"}, {"kategorie": "", "text": "Nach dem Ende des Zweiten Weltkriegs und der Befreiung Österreichs durch die [[Alliierten]] begann der Wiederaufbau des Landes. Am 27. April 1945 rief die provisorische Regierung unter Karl Renner die [[Zweite]] Republik aus. An diesem Tag wurde die Unabhängigkeitserklärung veröffentlicht, in der Österreich seine Loslösung vom nationalsozialistischen Deutschen Reich erklärte und seine Eigenstaatlichkeit wiederherstellte"}, {"kategorie": "", "text": "Die Verfassung der Ersten Republik aus dem Jahr 1920, die nach demokratischen Grundsätzen aufgebaut war, wurde wieder in Kraft gesetzt. Sie bildet die Grundlage der Zweiten Republik"}, {"kategorie": "", "text": "Ein zentraler Aspekt der Zweiten Republik ist die [[immerwährende]] Neutralität Österreichs, die am 26. Oktober 1955 im Zuge des [[Staatsvertrags]] beschlossen wurde. Der österreichische Staatsvertrag, der von den vier alliierten Mächten unterzeichnet wurde, garantierte die vollständige Souveränität Österreichs und beendete die Besatzung. In diesem Vertrag verpflichtete sich Österreich, militärisch neutral zu bleiben und keine Bündnisse mit anderen Staaten einzugehen. Der 26. Oktober wird seither als [[Nationalfeiertag]] begangen."}]'::jsonb, ''),
  ('grinzinga-allee', 'Grinzinga Allee', '', '', '', '', 'Grinzinger Allee', '[{"kategorie": "allg.", "text": "ruhige, grüne und exklusive Wohnstraße im 19. Wiener Gemeindebezirk ([[Döbling]]), die vom historischen und idyllischen [[Grinzing]] durch [[Oberdöbling]] bis nach [[Unterdöbling]] führt"}, {"kategorie": "", "text": "Sie ist benannt nach der Baumallee, welche an der von Wien nach Grinzing führenden Straße einst zur Abschirmung vor der Sonneneinstrahlung angepflanzt wurde"}, {"kategorie": "", "text": "Sie Grinzinger Allee verbindet die Weinberge und Weingüter der Region mit den urbanen Bereichen Wiens"}, {"kategorie": "", "text": "Die Straße bietet eine hohe Lebensqualität in einem gehobenen Wohngebiet, das sowohl Natur als auch gute Anbindungen an die Stadt bietet. Die Nähe zu den [[Heurigen]] und zum [[Wienerwald]] macht die Grinzinger Allee zu einer begehrten Wohnadresse in Wien."}]'::jsonb, ''),
  ('heilignschdaedta-laende', 'Heilignschdädta Lände', '', '', '', '', 'Heiligenstädter Lände', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 9. und 19. Wiener Gemeindebezirk ([[Alsergrund]] und [[Döbling]]), die entlang des Ufers des [[Donaukanals]] bis zur [[Heiligenstädter]] Brücke verläuft"}, {"kategorie": "", "text": "Die Straße ist nach der Uferlände des Donaukanals (zwischen [[Spittelauer]] und [[Nußdorfer]] Lände) benannt"}, {"kategorie": "", "text": "Sie ist sowohl eine zentrale Verkehrsader als auch eine bedeutende Verbindungsstraße im Norden Wiens. Die Heiligenstädter Lände verbindet das Stadtzentrum mit den nördlichen Bezirken Wiens und darüber hinaus mit dem Wiener Umland"}, {"kategorie": "", "text": "Die Heiligenstädter Lände verläuft entlang eines vorwiegend urbanen und industriell geprägten Bereichs des [[Donaukanals]]. In der Umgebung der Straße befinden sich zahlreiche Gewerbebetriebe, Industrieanlagen sowie einige Wohngebäude. Historisch gesehen war das Gebiet entlang des [[Donaukanals]] oft Standort von Hafenanlagen, Lagerhäusern und industriellen Einrichtungen. Heute gibt es entlang der Lände auch moderne Bürogebäude und vereinzelt Wohnprojekte."}]'::jsonb, ''),
  ('heilignschdaedta-bruckn', 'Heilignschdädta Bruckn', '', '', '', '', 'Heiligenstädter Brücke', '[{"kategorie": "allg.", "text": "Straßenbrücke über den [[Donaukanal]] in Wien. Sie verbindet den 19. Wiener Bezirk ([[Döbling]]) auf der rechten Seite des Donaukanals mit dem 20. Bezirk ([[Brigittenau]]) auf der linken Seite"}, {"kategorie": "", "text": "Die Brücke nach der ehemaligen Vorortgemeinde [[Heiligenstadt]] benannt und hieß früher (1889) \"Kaiser-Franz-Joseph-Regierungsjubiläums-Brücke\""}, {"kategorie": "", "text": "Am Ende des Zweiten Weltkriegs wurde die Brücke durch die zurückweichenden deutschen Truppen zerstört (Sprengung), konnte aber nach dem Krieg provisorisch instand gesetzt werden"}, {"kategorie": "", "text": "Zwischen 1959 und 1961 wurde die Heiligenstädter Brücke als Stahlbetonbrücke neu gebaut. Die Baukosten betrugen 15,5 Millionen Schilling. Bürgermeister Franz Jonas eröffnete die neue Brücke am 16. Dezember 1961 als 136. neugebaute kriegszerstörte Brücke. Mit der Fertigstellung der Heiligenstädter Brücke ist die letzte der zerstörten Donaukanalbrücken neu entstanden"}, {"kategorie": "", "text": "Heute ist die Brücke ist ein wichtiger Verkehrsknotenpunkt und spielt eine zentrale Rolle im Straßen- und Radverkehr zwischen den beiden Bezirken sowie für den Anschluss an das Wiener Umland."}]'::jsonb, ''),
  ('simmaringa-plotz', 'Simmaringa Plotz', '', '', '', '', 'Simmeringer Platz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 11. Wiener Gemeindebezirk ([[Simmering]]) und wichtiger Verkehrsknotenpunkt, der vor der Endstation der U3 beziehungsweise S-Bahn-Station Simmeringer Hauptstraße liegt\""}, {"kategorie": "", "text": "Der Simmeringer Platz ist benannt nach dem gleichnamigen ehemaligen Vorort beziehungsweise den elften Bezirk \"Simmering\""}, {"kategorie": "", "text": "Der Simmeringer Platz ist umgeben von einer Mischung aus Wohn- und Geschäftsgebäuden. In der Nähe befinden sich zahlreiche Geschäfte, Restaurants und Cafés, die den Platz zu einem lebendigen Zentrum im Bezirk machen"}, {"kategorie": "", "text": "Der Platz selbst ist ein funktionales urbanes Zentrum, das weniger durch seine ästhetische Gestaltung als durch seine verkehrstechnische und kommerzielle Bedeutung auffällt. Er bietet viele Einkaufsmöglichkeiten und ist ein Dreh- und Angelpunkt für die täglichen Erledigungen der Anwohner."}]'::jsonb, ''),
  ('simmaringa-friidhof', 'Simmaringa Friidhof', '', '', '', '', 'Simmeringer Friedhof', '[{"kategorie": "", "text": "Der Haupteingang befindet sich an der Adresse \"Unter der Kirche 5\". Der 1876 unter dem Kirchberg angelegte alte Teil enthält vor allem eine lange Reihe von Gräbern und wenige alte Steine, sehr bedeutend sind die neogotische Kapelle der Familie Rinnböck und das Grab des letzten Ortsrichters von Simmering. Der neue Teil weist einige schöne Grüfte des Bezirksbürgertums sowie von Fuhrwerksbesitzern, Gärtnern und Steinmetzen auf"}, {"kategorie": "", "text": "Seine Ursprünge hat der heutige Simmeringer Friedhof auf der Anhöhe, wo die Alt-Simmeringer Pfarrkirche St. Laurenz steht. Ihre Baugeschichte geht bis ins 13. Jahrhundert zurück. Grabungen haben erwiesen, dass das Grundstück um die Kirche schon früh als Gottesacker verwendet worden war"}, {"kategorie": "", "text": "Erst mit der Eingemeindung des Dorfes Simmering ins politische Wiener Stadtgebiet wurde der Simmeringer Friedhof auf die [[Simmeringer]] Haide unterhalb des Kirchhügels ausgeweitet"}, {"kategorie": "", "text": "Der Friedhof ist 56.955 Quadratmeter groß und verfügt über rund 8.000 Grabstellen. 1978-1979 wurde die Aufbahrungshalle nach Entwürfen des Architekten DI Erich Boltenstern umgebaut"}, {"kategorie": "", "text": "Auf dem Simmeringer Friedhof ist auch Josef Lang (* 11. März 1855 Simmering, † 21. Februar 1925 Wien), der letzter Scharfrichter Österreichs, begraben."}]'::jsonb, ''),
  ('strauss-lanner-park', 'Strauß-Lanner-Park', '', '', '', '', 'Strauß-Lanner-Park', '[{"kategorie": "allg.", "text": "öffentliche Grünanlage im 19. Wiener Gemeindebezirk, an der Straßengabelung der [[Grinzinger]] Allee mit der [[Sieveringer]] Straße"}, {"kategorie": "", "text": "Er wurde auf der Fläche des alten Döblinger Friedhofes errichtet und 1928 eröffnet und ist nach den beiden Komponisten Johann Strauß und Joseph Lanner benannt"}, {"kategorie": "", "text": "Denn auf dem ehemaligen Friedhof befand sich die letzte Ruhestätte der berühmten Wiener Musiker und Komponisten [[Johann]] Strauß (Vater) und Joseph Lanner"}, {"kategorie": "", "text": "Ihre Gebeine wurden dann 1904 auf den Wiener [[Zentralfriedhof]] umgebettet, währenddem die beiden Grabsteine in die Parkgestaltung miteinbezogen wurden und zentral im heutigen Strauß-Lanner-Park zu besichtigen sind."}]'::jsonb, ''),
  ('karmelitakloosta-deebling', 'Karmelitakloosta Deebling', '', '', '', '', 'Karmeliterkloster Döbling', '[{"kategorie": "allg.", "text": "\"Kloster des Ordens der Unbeschuhten Karmelitinnen im 19. Wiener Gemeindebezirk ([[Döbling]])\""}, {"kategorie": "", "text": "Das Kloster befindet sich in der [[Silbergasse]] und gehört zum Stadtteil [[Unterdöbling]]"}, {"kategorie": "", "text": "Der Karmelitenorden, der seinen Ursprung im 12. Jahrhundert hat, ist ein kontemplativer Orden, der sich auf das Gebet und die Meditation konzentriert. Die Unbeschuhten Karmelitinnen, ein Zweig des Karmelitenordens, leben in Klausur und widmen sich einem Leben in Stille, Gebet und Arbeit. Das Kloster in Döbling war eine Gründung, die im Laufe der Jahrzehnte zu einem wichtigen spirituellen Zentrum für die Gemeinschaft und die Gläubigen in der Umgebung wurde"}, {"kategorie": "", "text": "Für die Aufgabe ihres früheren Klosters hatten die Karmeliten vom Kaiser eine Entschädigung von 350.000 fl. (Gulden) aus einem Religionsfonds erhalten. Damit erwarben sie das Baugelände vom Orden der Serviten im 19. Wiener Bezirk und beauftragten den Architekten Richard Jordan mit der Ausarbeitung von Bauplänen für eine neue Klosteranlage, einschließlich der dazugehörigen Kirche"}, {"kategorie": "", "text": "Die Kirche, nördlich der Klosteranlage in der Silbergasse 35 im Wiener Ortsteil Döbling stehend, ist der Heiligen Familie geweiht. Der Bau des Gotteshauses im neuen Kloster dauerte von April 1899 bis zum August 1900. Am 18. August konnte die Pfarrei die Kirchweihe feiern und das Turmkreuz aufstecken. Und am 5. Dezember 1901 wurde die Weihe der 5 Glocken durchgeführt. Erst in den 1930er Jahren galt die Innenausstattung als vollendet"}]'::jsonb, ''),
  ('karmelitakiachn-deebling', 'Karmelitakiachn Deebling', '', '', '', '', 'Karmeliterkirche Döbling', '[{"kategorie": "allg.", "text": "\"Kirche des [[Karmeliterklosters]] Döbling im 19. Wiener Gemeindebezirk ([[Döbling]])\""}, {"kategorie": "", "text": "Die Kirche ist Teil des Klosterkomplexes in der [[Silbergasse]], im Stadtteil [[Unterdöbling]], und gehört zum Orden der Unbeschuhten Karmelitinnen"}, {"kategorie": "", "text": "Die Karmeliterkirche wurde zusammen mit dem Karmeliterkloster Döbling im Jahr 1901 errichtet. Sie diente von Anfang an als Klosterkirche der dort lebenden Unbeschuhten Karmelitinnen, einem Zweig des Karmelitenordens, der für sein kontemplatives und zurückgezogenes Leben bekannt ist"}, {"kategorie": "", "text": "Die Kirche ist eine mächtige Basilika mit zwei Türmen, die in Sichtziegelmauerwerk mit einem dreischiffigen, vierjochigen Langhaus (40 Meter lang, 25 Meter breit bzw. an der Vierung rund 32,40 Meter breit) ausgeführt wurde"}, {"kategorie": "", "text": "Die Turmunterbauten haben eine quadratische Grundfläche (Seitenlängen je 7,5 Meter) und auf ihnen erheben sich ab Unterkante Kirchendach achteckige schlanke Türme. Die Türme sind baugleich und mit je einem kupfergedeckten Spitzhelm abgeschlossen. Im Roman des Heimito von Doderer \"Die Dämonen\" wird die Gesamtansicht so beschrieben: ein „Gotteshaus mit dem ‚zum Himmel weisenden Finger’“"}, {"kategorie": "", "text": "Die Inneneinrichtung besticht insbesondere durch Elemente aus Jugendstil und Art Déco. Neben dem Hochaltar, den sechs Seitenaltären und der Theresienkapelle verfügt die Kirche über eine Kanzel, die von Ludwig Schadler aus Carrara-Marmor ausgeführt wurde"}, {"kategorie": "", "text": "Bereits im Ersten Weltkrieg, 1917, musste die Pfarrei die bronzenen Glocken als Metallspende für Kriegszwecke abliefern. Nach dem Ende des Krieges und nach der Inflation konnte der Orden im Jahr 1922 neue Glocken herstellen und installieren lassen. Doch im nächsten Krieg, im Jahr 1942 waren wieder vier Glocken zur Herstellung von Kriegsgerät zu spenden, die kleinste verblieb auf dem Turm. Erst in den 1950er Jahren brachte die Gemeinde das Geld auf, um sich wieder 5 neue Glocken gießen zu lassen. So entstand des heutige Geläut, das sich auf die Glockenstuben in den beiden Türmen verteilt"}, {"kategorie": "", "text": "Bedeutend ist auch die Orgel der Firma Rieger aus Jägerndorf, die im Jahr 1905 als Opus 1200 geliefert und auf der Empore installiert wurde. Die Orgelweihe fand zum Theresienfest, am Sonntag den 15. Oktober 1905, statt"}, {"kategorie": "", "text": "Heute ist die Kirche ist ein wichtiger Ort des kontemplativen Lebens und bietet auch Besuchern die Möglichkeit, an Gottesdiensten teilzunehmen und sich in die Stille und das Gebet zu vertiefen."}]'::jsonb, ''),
  ('neischdift-aum-woide', 'Neischdift aum Woide', '', '', '', '', 'Neustift am Walde', '[{"kategorie": "allg.", "text": "\"malerischer Ortsteil im 19. Wiener Bezirk ([[Döbling]]), der an [[Salmannsdorf]] und [[Sievering]] grenzt und sich am Rand des [[Wienerwalds]] erstreckt\""}, {"kategorie": "", "text": "Der Ortsteil ist weit über die Stadtgrenzen hinaus für seine Weinberge, die traditionelle [[Heurigenkultur]] und die charmante, fast dörfliche Atmosphäre bekannt"}, {"kategorie": "", "text": "Die Geschichte von Neustift am Walde reicht bis ins Mittelalter zurück. Der Ort wurde im 12. Jahrhundert erstmals urkundlich erwähnt und entwickelte sich über die Jahrhunderte hinweg zu einem wichtigen Zentrum des Weinbaus"}, {"kategorie": "", "text": "Der Name \"Neustift\" leitet sich von den Stiften ab, den kirchlichen Stiftungen, die das Gebiet ursprünglich nutzten. Schon im Mittelalter spielten die Weinberge von Neustift eine zentrale Rolle im wirtschaftlichen und gesellschaftlichen Leben des Ortes"}, {"kategorie": "", "text": "Im Jahr 1892 wurde Neustift am Walde nach Wien eingemeindet und ist seither Teil des 19. Bezirks (Döbling). Trotz der Eingemeindung hat sich Neustift seinen ländlichen Charakter weitgehend bewahrt"}, {"kategorie": "", "text": "Die Weinberge, die den Ort umgeben, gehören zu den bedeutendsten Weinbaugebieten Wiens. In Neustift wird traditionell Weißwein angebaut, darunter die für Wien typischen Sorten wie [[Grüner]] Veltliner, [[Riesling]] und [[Gemischter]] Satz"}, {"kategorie": "", "text": "Ein besonderes Merkmal Neustifts sind die zahlreichen Heurigenlokale sowie der Neustifter Kirtag, ein traditionelles Volksfest, das jeden August stattfindet. Ein besonderes Ritual des Kirtags ist das Fasslrutschen, ein Brauch, bei dem Besucher auf einem großen Weinfass hinunterrutschen. Es wird gesagt, dass dieser Brauch Glück und ein langes Leben bringen soll"}, {"kategorie": "", "text": "Neustift am Walde hat sich seinen dörflichen Charme bewahrt, obwohl es heute ein Teil der Millionenstadt Wien ist. Viele der alten Weinbauernhäuser, Villen und Heurigenlokale sind in ihrer ursprünglichen Form erhalten geblieben oder wurden liebevoll restauriert. Besonders in den verwinkelten Seitenstraßen finden sich Gebäude, die das traditionelle Bild eines Weinortes vermitteln."}]'::jsonb, ''),
  ('pfoakiachn-neischdift-aum-woide', 'Pfoakiachn Neischdift aum Woide', '', '', '', '', 'Pfarrkirche Neustift am Walde', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 19. Wiener Gemeindebezirk à(Döbling), im malerischen Ortsteil [[Neustift]] am Walde (auch bekannt als \"Pfarrkirche zur Heiligen Dreifaltigkeit\")"}, {"kategorie": "", "text": "Die Pfarrkirche in Neustift am Walde geht auf das Jahr 1736 zurück, als sie auf Initiative der Anwohner errichtet wurde. Die Kirche war ursprünglich eine Filialkirche der Pfarre [[Sievering]], erhielt aber im Jahr 1784 unter Kaiser [[Joseph]] II. den Status einer eigenständigen Pfarre. Die Kirche ist der Heiligen Dreifaltigkeit geweiht, was ihr auch den Beinamen \"Dreifaltigkeitskirche\" verleiht"}, {"kategorie": "", "text": "Die Gründungsgeschichte der Kirche ist eng mit der Tradition des Weinbaus in Neustift verbunden. Die Kirche diente lange Zeit als geistliches Zentrum für die Weinbauern der Umgebung, die hier regelmäßig Gottesdienste besuchten und die Kirche auch in ihre festlichen Traditionen einbezogen, wie etwa den alljährlichen Neustifter Kirtag"}, {"kategorie": "", "text": "Die Kirche entwickelte sich von einer kleinen, von Peststiftern errichteten Kapelle zu einer vollwertigen Pfarrkirche im Zuge der Reformen Kaiser Josephs II. Die Kirche vereint in ihrer Architektur und Ausstattung barocke und klassizistische Elemente und ist eng mit der Geschichte der Pest und der Pestheiligen in Wien verbunden"}, {"kategorie": "", "text": "Im Jahr 1713 stiftete der italienische Kaufmann Marco Abundio eine Kapelle, die den Pestheiligen Rochus, Sebastian, Karl Borromäus, Franz Xaver und Rosalia geweiht war. 1784, nach der Aufhebung des Chorherrenklosters St. Dorothea durch Kaiser Joseph II., wurde Neustift am Walde eine eigenständige Pfarre. Die Kapelle wurde zwischen 1783 und 1785 durch Anbauten zur Pfarrkirche erweitert. 1851 erhielt die Kirche einen neuen Kirchturm und erfuhr weitere bauliche Veränderungen:  6. Der klassizistische Hochaltar stammt aus 1786 und enthält ein Altarbild des Barockmalers Martino Altomonte, das die Pestheiligen zeigt. Die Seitenaltäre und die Orgel aus dem 19. Jahrhundert sowie die Kirchenfenster aus den 1990er Jahren ergänzen die Innenausstattung. Vier barocke Heiligenstatuen und ein Glockengeläut von 1949 prägen das äußere Erscheinungsbild der Kirche"}, {"kategorie": "", "text": "Die Orgel der Pfarrkirche wurde im Jahr 1855 von dem Klosterneuburger Orgelbauer Franz Reusch gefertigt und gehört zu seinen frühen Werken. Sie umfasst acht Register und ist ein bedeutendes historisches Instrument."}]'::jsonb, ''),
  ('kiachn-sankt-georg', 'Kiachn Sankt Georg', '', '', '', '', 'Kirche Sankt Georg', '[{"kategorie": "allg.", "text": "römisch-katholische Pfarrkirche im [[Kahlenbergerdorf]] im 19. Wiener Gemeindebezirk ([[Döbling]])"}, {"kategorie": "", "text": "Sie ist dem heiligen Georg geweiht und stellt ein wichtiges religiöses und historisches Zentrum des Kahlenbergerdorfs dar, einem kleinen, traditionsreichen Stadtteil am Fuße des [[Kahlenbergs]] und [[Leopoldsbergs]]"}, {"kategorie": "", "text": "Die Kirche Sankt Georg wurde ursprünglich im Mittelalter errichtet, wobei ihre Ursprünge bis ins 12. Jahrhundert zurückreichen. Sie gehört somit zu den ältesten Kirchengebäuden in der Region"}, {"kategorie": "", "text": "Das heutige Aussehen der Kirche stammt aus dem Barock, nachdem sie im 17. Jahrhundert nach den Zerstörungen durch die Türkenbelagerungen wiederaufgebaut wurde. Die Kirche wurde mehrmals restauriert und erweitert, wobei ihr barocker Charakter erhalten blieb, was sich insbesondere in der Gestaltung der Fassade und im Innenraum widerspiegelt"}, {"kategorie": "", "text": "Der heilige Georg, der Schutzpatron der Kirche, ist in der christlichen Tradition besonders als Drachentöter bekannt und wird oft als Symbol für den Sieg des Guten über das Böse dargestellt. Dies spiegelt sich in der Kunst und den Darstellungen innerhalb der Kirche wider."}]'::jsonb, ''),
  ('kiachn-sankt-brigitta', 'Kiachn Sankt Brigitta', '', '', '', '', 'Kirche Sankt Brigitta', '[{"kategorie": "allg.", "text": "römisch-katholische Pfarrkirche im 20. Wiener Gemeindebezirk ([[Brigittenau]])"}, {"kategorie": "", "text": "Die Kirche ist nach der heiligen Brigitta von Schweden benannt, einer bedeutenden Heiligen der katholischen Kirche, die im 14. Jahrhundert lebte und für ihre mystischen Erfahrungen und ihr Engagement für den Glauben bekannt ist. Ihr Name gab auch dem gesamten Bezirk [[Brigittenau]] seinen Namen"}, {"kategorie": "", "text": "Die Kirche wurde in der zweiten Hälfte des 19. Jahrhunderts erbaut. Der Bau begann 1867, und die Kirche wurde 1874 geweiht. Die Errichtung der Kirche war Teil der raschen städtebaulichen Entwicklung der Brigittenau, die durch die [[Donauregulierung]] und den anschließenden Bauboom ermöglicht wurde"}, {"kategorie": "", "text": "Die Kirche ist im neugotischen Stil erbaut, was typisch für viele Kirchenbauten in Wien aus dieser Zeit ist. Der neugotische Stil zeichnet sich durch hohe, spitzbogige Fenster, reich verzierte Fassaden und Türme sowie eine klare vertikale Ausrichtung aus"}, {"kategorie": "", "text": "Die Kirche hat eine markante Fassade mit einem hohen Turm, der das umliegende Stadtbild prägt. Der Turm ist ein weithin sichtbares Wahrzeichen der Brigittenau. Die Kirche besitzt auch eine beeindruckende Orgel, die regelmäßig bei Gottesdiensten und Konzerten zum Einsatz kommt."}]'::jsonb, ''),
  ('schloss-poetzleinsduaf', 'Schloss Pötzleinsduaf', '', '', '', '', 'Schloss Pötzleinsdorf', '[{"kategorie": "allg.", "text": "historisches Gebäude im 18. Wiener Gemeindebezirk ([[Währing]]) im Stadtteil [[Pötzleinsdorf]]"}, {"kategorie": "", "text": "Das Schloss ist Teil eines großen, parkähnlichen Anwesens, das heute als öffentlicher Park ([[Pötzleinsdorfer Schlosspark]]), genutzt wird. Das Schloss selbst ist ein bedeutendes Beispiel für die Architektur und die Geschichte der Wiener Vororte und war über Jahrhunderte hinweg ein Rückzugsort für die Wiener Aristokratie"}, {"kategorie": "", "text": "Das Schloss Pötzleinsdorf geht auf einen Gutshof zurück, der im Mittelalter bestand. Im 18. Jahrhundert wurde das Anwesen von verschiedenen Adelsfamilien erweitert und zu einem repräsentativen Landsitz umgebaut. Im Jahr 1797 erwarb der Wiener Bankier und Industrielle Johann Heinrich von Geymüller das Anwesen und ließ es im Stil des Biedermeier und [[Klassizismus]] umgestalten"}, {"kategorie": "", "text": "Das Schloss und der dazugehörige Park entwickelten sich zu einem beliebten Rückzugsort für die Wiener Gesellschaft. Besonders der großzügige Landschaftspark, der im englischen Stil angelegt wurde, zog Besucher an. Das Schloss wurde in dieser Zeit von verschiedenen prominenten Persönlichkeiten besucht, darunter Mitglieder der österreichischen Kaiserfamilie"}, {"kategorie": "", "text": "Der Park wurde 1935 von der Stadt Wien erworben und für die Öffentlichkeit zugänglich gemacht"}, {"kategorie": "", "text": "Das Schloss Pötzleinsdorf wurde im klassizistischen Stil umgebaut und erweitert. Es zeichnet sich durch eine schlichte, elegante Fassade mit klaren Linien und symmetrischen Proportionen aus. Der Einfluss des Biedermeier-Stils ist im Inneren des Gebäudes sichtbar, insbesondere in den repräsentativen Räumen, die für gesellschaftliche Anlässe genutzt wurden."}]'::jsonb, ''),
  ('poetzleinsduafa-schlosspark', 'Pötzleinsduafa Schlosspark', '', '', '', '', 'Pötzleinsdorfer Schlosspark', '[{"kategorie": "allg.", "text": "weitläufige, öffentliche Parkanlage im 18. Wiener Gemeindebezirk ([[Währing]]) im Stadtteil [[Pötzleinsdorf]]"}, {"kategorie": "", "text": "Er gehört zu den größten und schönsten Parks in Wien und ist bekannt für seine malerische Landschaftsgestaltung im englischen Stil, seine historischen Elemente und seine Bedeutung als Erholungsraum für die Wiener Bevölkerung"}, {"kategorie": "", "text": "Im 19. Jahrhundert ließ Johann Heinrich von Geymüller, der das Schloss 1797 erworben hatte, den Park im englischen Landschaftsstil umgestalten. Der englische Stil zeichnet sich durch weite Wiesen, malerische Baumgruppen, geschwungene Wege und Teiche aus, die eine natürliche, aber kunstvoll gestaltete Landschaft simulieren"}, {"kategorie": "", "text": "1935 erwarb die Stadt Wien das Anwesen und machte den Park für die Öffentlichkeit zugänglich. Seitdem dient der Pötzleinsdorfer Schlosspark als öffentlicher Erholungsraum"}, {"kategorie": "", "text": "Im Park finden sich mehrere historische Elemente wie kleine Pavillons, Brücken und Skulpturen, die aus der Zeit stammen, als der Park noch zum Schloss gehörte. Diese Elemente tragen zum romantischen Charakter des Parks bei"}]'::jsonb, ''),
  ('kaisa-mathias', 'Kaisa Mathias', '', '', '', '', 'Kaiser Mathias', '[{"kategorie": "allg.", "text": "\"römisch-deutscher Kaiser aus dem Haus Habsburg, der von 1612 bis 1619 regierte\""}, {"kategorie": "", "text": "Er war auch König von Böhmen, König von Ungarn und Erzherzog von Österreich. Matthias ist eine wichtige, aber oft weniger bekannte Figur in der Geschichte des Heiligen Römischen Reiches, besonders in der Zeit vor dem Dreißigjährigen Krieg"}, {"kategorie": "", "text": "Matthias wurde am 24. Februar 1557 als dritter Sohn von [[Kaiser]] Maximilian II. und [[Maria]] von Spanien geboren. Er war der Neffe von [[Kaiser]] Karl V. und gehörte somit zu einer der mächtigsten Dynastien Europas"}, {"kategorie": "", "text": "Matthias wurde 1593 zum Erzherzog von Österreich ernannt. In dieser Position zeigte er administrative Fähigkeiten und versuchte, die katholische Kirche zu stärken, während er gleichzeitig versuchte, die protestantischen Stände zu besänftigen"}, {"kategorie": "", "text": "Kaiser Matthias starb am 20. März 1619 in Wien. Da er keine direkten Nachkommen hatte, ging die Kaiserkrone an seinen Cousin [[Ferdinand]] II. über, dessen harte Rekatholisierungsmaßnahmen den Dreißigjährigen Krieg weiter anheizten"}]'::jsonb, ''),
  ('kaisa-maximilan-ii', 'Kaisa Maximilan II.', '', '', '', '', 'Kaiser Maximilan II.', '[{"kategorie": "allg.", "text": "\"römisch-deutscher Kaiser aus dem Haus Habsburg, der von 1564 bis zu seinem Tod im Jahr 1576 regierte. Er war eine zentrale Figur der europäischen Politik des 16. Jahrhunderts und versuchte, das Heilige Römische Reich in einer Zeit großer religiöser Spannungen zu regieren\""}, {"kategorie": "", "text": "Maximilian II. wurde am 31. Juli 1527 in Wien als Sohn von [[Kaiser]] Ferdinand I. und [[Anna]] von Böhmen und Ungarn geboren. Er gehörte damit zur mächtigen Habsburger-Dynastie, die weite Teile Europas beherrschte"}, {"kategorie": "", "text": "Er wurde 1548 Erzherzog von Österreich, 1562 zum König von Böhmen und 1563 zum König von Ungarn gekrönt"}, {"kategorie": "", "text": "Nach dem Tod seines Vaters [[Ferdinand]] I. im Jahr 1564 wurde Maximilian II. römisch-deutscher Kaiser. Er regierte über das Heilige Römische Reich und die Habsburgischen Erblande"}, {"kategorie": "", "text": "Maximilian II. heiratete 1548 seine Cousine Maria von Spanien, die Tochter von Kaiser [[Karl]] V. und Isabella von Portugal. Aus dieser Ehe gingen 16 Kinder hervor, darunter die späteren Kaiser Rudolf II. und Matthias."}]'::jsonb, ''),
  ('dresdna-schdrossn', 'Dresdna Schdrossn', '', '', '', '', 'Dresdner Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 20. Wiener Gemeindebezirk ([[Brigittenau]])\""}, {"kategorie": "", "text": "Sie erstreckt sich in Nord-Süd-Richtung und verbindet den 20. Bezirk mit dem nördlichen Teil Wiens"}, {"kategorie": "", "text": "Die Dresdner Straße wurde nach der Stadt Dresden (Hauptstadt von Sachsen) benannt, mit der Wien im 19. Jahrhundert enge kulturelle und wirtschaftliche Verbindungen pflegte (als Dank für eine Wiener Straße in Dresden). Sie entstand in der zweiten Hälfte des 19. Jahrhunderts im Zuge der Stadterweiterung Wiens und wurde schrittweise zu einer wichtigen Verkehrsader"}, {"kategorie": "", "text": "Die alleeartige Straße wird ab der Kreuzung mit dem [[Höchstädtplatz]] und der [[Stromstraße]] in südlicher Richtung von der Straßenbahn befahren. An der Kreuzung mit der [[Hellwagstraße]] liegt die U-Bahn-Station Dresdner Straße der Linie U6"}, {"kategorie": "", "text": "Entlang der Dresdner Straße gibt es zahlreiche Geschäfte, Supermärkte, Restaurants sowie Dienstleistungsbetriebe. Sie ist von gemischter Bebauung geprägt – von traditionellen Wohnhäusern bis zu modernen Geschäftsbauten. Zudem liegt sie in der Nähe von größeren städtischen Einrichtungen, wie etwa dem [[Millennium]] Tower."}]'::jsonb, ''),
  ('friidrich-engls-plotz', 'Friidrich-Engls-Plotz', '', '', '', '', 'Friedrich-Engels-Platz', '[{"kategorie": "allg.", "text": "bedeutender Platz im 20. Wiener Gemeindebezirk ([[Brigittenau]]), der nach dem deutschen Philosophen, Sozialisten und Mitbegründer des Marxismus, Friedrich Engels (1820–1895), benannt ist"}, {"kategorie": "", "text": "Der Platz erhielt seinen Namen im Jahr 1947 als Zeichen der ideologischen Nähe der damaligen politischen Führung Wiens zur Arbeiterbewegung und zur sozialistischen Tradition. Friedrich Engels, der neben Karl Marx als einer der führenden Köpfe des wissenschaftlichen Sozialismus gilt, war eine wichtige Symbolfigur für die Arbeiterbewegung, und die Benennung des Platzes spiegelt diese ideologischen Verbindungen wider"}, {"kategorie": "", "text": "Der Friedrich-Engels-Platz liegt im nördlichen Teil von Brigittenau, in der Nähe der Donau, und markiert einen wichtigen Zugang zur Floridsdorfer Brücke, die den 20. Bezirk mit dem gegenüberliegenden Bezirk Floridsdorf auf der anderen Seite der Donau verbindet"}, {"kategorie": "", "text": "Der Friedrich-Engels-Platz ist nicht nur ein Verkehrsknotenpunkt, sondern auch ein symbolträchtiger Ort für die Arbeiterbewegung und die sozialistische Geschichte Wiens. Heute ist der Platz ist von großflächigen Wohnsiedlungen und Geschäftshäusern umgeben, die in der Nachkriegszeit errichtet wurden. In der Nähe befindet sich auch der markante [[Friedrich-Engelsplatz-Hof]], eine kommunale Wohnanlage, die typisch für den sozialen Wohnbau in Wien ist."}]'::jsonb, ''),
  ('friidrich-engls-plotz-hof', 'Friidrich-Engls-Plotz-Hof', '', '', '', '', 'Friedrich-Engels-Platz-Hof', '[{"kategorie": "allg.", "text": "\"bedeutende kommunale Wohnanlage in Wien, die sich am [[Friedrich-Engels-Platz]] im 20. Bezirk ([[Brigittenau]]) befindet\""}, {"kategorie": "", "text": "Sie wurde 1930-1933 von Rudolf Perco, einem Schüler Otto Wagners, erbaut und ist ein Beispiel für das [[Rote Wien]], eine Epoche, in der die sozialdemokratische Stadtregierung großflächig [[Gemeindebauten]] errichtete. Der Hof besteht aus mehreren großen Wohnblöcken, die um Innenhöfe angeordnet sind, und beherbergt 1.476 Wohnungen"}, {"kategorie": "", "text": "Der Hof galt als eines der stärksten Bollwerke des [[Republikanischen]] Schutzbunds, fiel jedoch bereits am 12. Februar 1934 in die Hände der Regierungstruppen"}, {"kategorie": "", "text": "Im April 1945 bestand vor der Floridsdorfer Brücke der letzte Brückenkopf der zurückweichenden deutschen Truppen am Südufer der Donau, im Volksmund „Engelshof\" genannt"}, {"kategorie": "", "text": "Der Wohnbau liegt direkt am Friedrich-Engels-Platz, einem wichtigen Verkehrsknotenpunkt im Norden von Brigittenau. Durch die Nähe zur Donau und zur Floridsdorfer Brücke ist der Friedrich-Engels-Platz-Hof gut an das Verkehrsnetz angebunden und bietet den Bewohnern eine zentrale Lage mit guter Infrastruktur."}]'::jsonb, ''),
  ('republikanischa-schutzbund', 'Republikanischa Schutzbund', '', '', '', '', 'Republikanischer Schutzbund', '[{"kategorie": "allg.", "text": "\"paramilitärische Organisation der Sozialdemokratischen Arbeiterpartei Österreichs (SDAP) in der [[Ersten]] Republik (1918–1934)\""}, {"kategorie": "", "text": "Er wurde 1923 gegründet und diente in erster Linie dem Schutz der sozialdemokratischen Bewegung sowie der Arbeiterklasse vor rechtsextremen und monarchistischen Kräften, insbesondere gegen die aufstrebenden faschistischen Gruppierungen und den [[Heimwehrverband]], der von konservativen Kräften unterstützt wurde"}, {"kategorie": "", "text": "Der Republikanische Schutzbund wurde als Reaktion auf die politischen Spannungen der Ersten Republik gegründet, die nach dem Zerfall der [[Habsburgermonarchie]] von schweren sozialen und politischen Konflikten geprägt war. Seine Hauptaufgabe war der Schutz der republikanischen Demokratie und die Verteidigung der Interessen der Arbeiterklasse. Die SDAP, die die Stadt Wien und zahlreiche wichtige Institutionen dominierte, betrachtete den Schutzbund als eine Möglichkeit, die politische Macht der Arbeiterschaft zu sichern und zu verteidigen"}, {"kategorie": "", "text": "Der Schutzbund war in erster Linie eine Massenorganisation und hatte zeitweise über 80.000 Mitglieder, die größtenteils aus der Arbeiterschaft kamen. Die Organisation war gut strukturiert und verfügte über eine militärische Hierarchie, deren Mitglieder paramilitärisch geschult wurden. Der Schutzbund hatte enge Verbindungen zu den sozialdemokratischen Gewerkschaften und war in Wien besonders stark vertreten, wo die Sozialdemokratie durch den sogenannten [[Austromarxismus]] die Politik prägte"}, {"kategorie": "", "text": "In den frühen 1930er Jahren eskalierten die politischen Konflikte in Österreich zwischen den sozialdemokratischen Kräften und den konservativ-autoritären Gruppen, die zunehmend faschistische Ideologien übernahmen. Diese Spannungen gipfelten im österreichischen [[Bürgerkrieg]] von 1934, der als Februaraufstand in die Geschichte einging. Der Republikanische Schutzbund stellte sich in diesem bewaffneten Konflikt gegen die Regierung des autoritären Ständestaats, die sich auf die paramilitärische [[Heimwehr]] und die regulären Streitkräfte stützte"}, {"kategorie": "", "text": "Der Aufstand von 1934 wurde brutal niedergeschlagen, und der Republikanische Schutzbund wurde nach der Niederlage aufgelöst. Nach dem Bürgerkrieg errichtete die konservative Regierung den autoritären Ständestaat, der die Sozialdemokratie und ihre Organisationen, einschließlich des Schutzbundes, verbot. Viele Mitglieder des Schutzbundes wurden inhaftiert, ins Exil gezwungen oder verfolgt"}, {"kategorie": "", "text": "Der Republikanische Schutzbund steht symbolisch für die Klassenkämpfe und politischen Spannungen in der [[Ersten]] Republik und war Ausdruck der tiefen Spaltung zwischen den sozialdemokratischen und den konservativen Kräften in der österreichischen Gesellschaft."}]'::jsonb, ''),
  ('austro-marxismus', 'Austro-Marxismus', '', '', '', '', 'Austro-Marxismus', '[{"kategorie": "allg.", "text": "\"politische Strömung innerhalb der sozialistischen Bewegung in Österreich, die von den 1920er bis zu den 1930er Jahren maßgeblich von der Sozialdemokratischen Arbeiterpartei (SDAP) vertreten wurde\""}, {"kategorie": "", "text": "Diese Strömung versuchte, den Marxismus mit der spezifischen Situation der multinationalen [[Habsburgermonarchie]] zu verbinden"}, {"kategorie": "", "text": "Ein zentrales Merkmal des Austro-Marxismus war der Fokus auf eine friedliche und demokratische Entwicklung hin zum Sozialismus, im Gegensatz zur bolschewistischen Revolution"}, {"kategorie": "", "text": "Führende Vertreter wie Otto Bauer und Karl Renner entwickelten Theorien zur \"nationalen Autonomie\" und zur klassenübergreifenden Zusammenarbeit"}, {"kategorie": "", "text": "Eine der bedeutendsten Umsetzungen des Austro-Marxismus war das [[Rote Wien]] in den 1920er Jahren, wo unter sozialdemokratischer Führung umfassende Sozialreformen, Wohnbauprojekte und soziale Sicherungssysteme umgesetzt wurden"}, {"kategorie": "", "text": "Der Austro-Marxismus versuchte, den revolutionären Kampf mit parlamentarischen und reformistischen Ansätzen zu verbinden, blieb jedoch letztlich politisch erfolglos, da er durch die Errichtung der Diktatur in Österreich 1934 ([[Februarkämpfe]] von 1934) und die anschließende Annexion durch das nationalsozialistische Deutschland ([[Anschluss]]) unterbrochen wurde."}]'::jsonb, ''),
  ('otto-bauer-gasse', 'Otto-Bauer-Gasse', '', '', '', '', 'Otto-Bauer-Gasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 6. Wiener Gemeindebezirk ([[Mariahilf]]), die nach dem prominenten österreichischen Sozialisten und Theoretiker Otto Bauer benannt wurde\""}, {"kategorie": "", "text": "Bauer war eine zentrale Figur des [[Austro-Marxismus]] und führender Kopf der Sozialdemokratischen Arbeiterpartei Österreichs (SDAP). Er spielte eine Schlüsselrolle in der österreichischen Arbeiterbewegung und in den politischen Entwicklungen der [[Ersten]] Republik"}, {"kategorie": "", "text": "Otto Bauer selbst war nicht nur politisch einflussreich, sondern auch ein bedeutender Denker und Autor. Er war einer der Hauptvertreter des [[Austro-Marxismus]] und verfasste wegweisende Werke zur nationalen Frage und zur sozialistischen Theorie. Seine Ideen zur Nationalitätenpolitik in der vielsprachigen [[Habsburgermonarchie]] prägten die politische Landschaft seiner Zeit"}, {"kategorie": "", "text": "Heute ist die Otto-Bauer-Gasse eine eher ruhige Wohnstraße, gesäumt von historischen Gebäuden aus der [[Gründerzeit]]. Sie liegt in einem dicht besiedelten Teil Wiens und ist für ihre Nähe zur belebten [[Mariahilfer]] Straße, einer der größten Einkaufsstraßen Wiens, bekannt"}, {"kategorie": "", "text": "Die Umgebung ist von einer Mischung aus Wohnhäusern, Geschäften und Büros geprägt."}]'::jsonb, ''),
  ('vatalaendische-front', 'Vataländische Front', '', '', '', '', 'Vaterländische Front', '[{"kategorie": "allg.", "text": "\"politische Massenorganisation, die 1933 in Österreich unter der Regierung von Engelbert [[Dollfuß]] gegründet wurde\" (abgekürzt: \"VF\")"}, {"kategorie": "", "text": "Die Vaterländische Front sollte als Einheitspartei alle politischen Kräfte, insbesondere konservative, katholische und monarchistische Elemente, in einem autoritären [[Ständestaat]] vereinen"}, {"kategorie": "", "text": "Die Vaterländische Front diente der Abschaffung der parlamentarischen Demokratie und der Einführung einer Diktatur im Rahmen des [[Austrofaschismus]]"}, {"kategorie": "", "text": "Sie war die einzige erlaubte politische Organisation und verfolgte eine strikte antimarxistische und antidemokratische Politik. Ihr Ziel war die Abwehr sozialistischer und nationalsozialistischer Tendenzen"}, {"kategorie": "", "text": "Nach der Zerschlagung der Sozialdemokratie im [[Bürgerkrieg]] 1934 war die Vaterländische Front die einzige legale politische Organisation im Land. Unter der Führung von Dollfuß'' Nachfolger, Kurt Schuschnigg, blieb die VF bis 1938 an der Macht, bis der [[Anschluss]] an das nationalsozialistische Deutschland die Organisation auflöste."}]'::jsonb, ''),
  ('haus-habsburg', 'Haus Habsburg', '', '', '', '', 'Haus Habsburg', '[{"kategorie": "allg.", "text": "\"eine der bedeutendsten und langlebigsten Herrscherfamilien Europas, die über mehrere Jahrhunderte hinweg große Teile Europas regierte\""}, {"kategorie": "", "text": "Ihr Ursprung liegt im 10. Jahrhundert, und sie benannte sich nach der Habsburg, einer Burg im heutigen Kanton Aargau in der Schweiz"}, {"kategorie": "", "text": "Die Dynastie erlangte im 15. Jahrhundert durch geschickte Heiratspolitik und territoriale Ausweitung großen Einfluss. Ihre Herrschaft umfasste das Heilige Römische Reich, Spanien und weite Teile Mitteleuropas, insbesondere das Gebiet der späteren [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Wichtige Herrscher waren: (i) [[Maximilian]] I. (1459–1519): Er führte die Familie durch Heiratspolitik zur Macht in ganz Europa;  (ii) [[Karl]] V. (1500–1558): Er herrschte über ein riesiges Reich, in dem „die Sonne nie unterging“, einschließlich Spanien, der Niederlande und der Kolonien in der Neuen Welt;  (iii) [[Maria]] Theresia (1717–1780): Sie reformierte das [[Habsburgerreich]] und sicherte die dynastische Macht im 18. Jahrhundert;  sowie (iv) [[Franz]] Joseph I. (1830–1916): Herrschte fast 70 Jahre und führte die Monarchie bis zum Ersten Weltkrieg"}, {"kategorie": "", "text": "Die Habsburgerdynastie endete offiziell 1918 mit dem Zerfall der [[Habsburgermonarchie]] nach dem Ersten Weltkrieg. Sie hinterließ jedoch einen nachhaltigen Einfluss auf die europäische Geschichte, insbesondere durch die prägenden Entwicklungen in Österreich, Spanien und dem [[Heiligen]] Römischen Reich."}]'::jsonb, ''),
  ('ausgleich-von-1867', 'Ausgleich von 1867', '', '', '', '', 'Ausgleich von 1867', '[{"kategorie": "allg.", "text": "\"Vereinbarung zwischen dem österreichischen Kaiser [[Franz]] Joseph I. und der ungarischen Führung, die zur Schaffung der [[Doppelmonarchie]] Österreich-Ungarn führte\""}, {"kategorie": "", "text": "Diese Vereinbarung stellte eine Reaktion auf die zunehmenden nationalen Spannungen im Habsburgerreich dar und teilte das Reich in zwei weitgehend autonome Teile: das österreichische Kaisertum ([[Kaisertum]] Österreich) und das Königreich Ungarn"}, {"kategorie": "", "text": "Beide Länder hatten eigene Regierungen, Parlamente und Verwaltungen, blieben aber unter der gemeinsamen Herrschaft des Kaisers/Königs [[Franz]] Joseph I. verbunden. Außenpolitik, Militär und Finanzen wurden gemeinsam verwaltet."}]'::jsonb, ''),
  ('oestarreichisch-ungarischer-ausgleich-von-1867', 'Östarreichisch-ungarischer Ausgleich von 1867', '', '', '', '', 'Österreichisch-ungarischer Ausgleich von 1867', '[{"kategorie": "allg.", "text": "\"Vereinbarung zwischen dem österreichischen Kaiser [[Franz]] Joseph I. und der ungarischen Führung, die zur Schaffung der [[Doppelmonarchie]] Österreich-Ungarn führte\""}, {"kategorie": "", "text": "Diese Vereinbarung stellte eine Reaktion auf die zunehmenden nationalen Spannungen im Habsburgerreich dar und teilte das Reich in zwei weitgehend autonome Teile: das österreichische Kaisertum ([[Kaisertum]] Österreich) und das Königreich Ungarn"}, {"kategorie": "", "text": "Beide Länder hatten eigene Regierungen, Parlamente und Verwaltungen, blieben aber unter der gemeinsamen Herrschaft des Kaisers/Königs [[Franz]] Joseph I. verbunden. Außenpolitik, Militär und Finanzen wurden gemeinsam verwaltet."}]'::jsonb, ''),
  ('deitscha-bund', 'Deitscha Bund', '', '', '', '', 'Deutscher Bund', '[{"kategorie": "allg.", "text": "\"loser Staatenbund, der 1815 auf dem [[Wiener]] Kongress als Nachfolger des [[Heiligen]] Römischen Reiches gegründet wurde\""}, {"kategorie": "", "text": "Er bestand aus 39 souveränen Fürstentümern und freien Städten, darunter Preußen, Österreich und kleinere deutsche Staaten"}, {"kategorie": "", "text": "Ziel des Bundes war die Sicherung der politischen Stabilität in den deutschsprachigen Gebieten"}, {"kategorie": "", "text": "Der Deutsche Bund hatte keine zentrale Regierung oder einheitliche Verfassung, sondern war eine föderale Struktur mit einem Bundestag in Frankfurt am Main"}, {"kategorie": "", "text": "Er endete 1866 nach dem [[Deutschen]] Krieg zwischen Preußen und Österreich."}]'::jsonb, '')
